// Ami des mots — v6.49 : le labo des sciences passe à 20 questions par thème (espace, fusées, corps humain, médecine).
// Chargé après js/sciences.js : ajoute les questions à SCIENCES.Q et leurs traductions à SCIENCES_LANGUES (en, es, de, it, pt).
// Format de chaque langue : [question, bonne réponse, [[mauvaise réponse, clash], …], explication] — même ordre partout.
(function(){
  'use strict';
  const S = window.SCIENCES, LG = window.SCIENCES_LANGUES || {};
  if(!S) return;
  const P = (id, theme, t) => {
    if(S.Q.some(x => x[0] === id)) return;
    const f = t.fr; S.Q.push([id, theme, f[0], f[1], f[2], f[3]]);
    for(const l of ['en', 'es', 'de', 'it', 'pt']) if(LG[l] && LG[l].q && t[l]) LG[l].q[id] = t[l];
  };

  // ── 🪐 Planètes et espace ──
  P('lune-face', 'espace', {
    fr:['Pourquoi voit-on toujours la même face de la Lune ?', 'Elle tourne sur elle-même en autant de temps qu’autour de la Terre', [['Elle ne tourne pas sur elle-même', 'Elle tourne ! Juste au même rythme que son tour de la Terre, comme une danseuse qui te regarde toujours.'], ['L’autre face est dans la nuit pour toujours', 'La face cachée reçoit le Soleil aussi ! On ne la voit pas d’ici, c’est tout.']], 'La Lune fait un tour sur elle-même en environ 27 jours, le même temps qu’un tour de la Terre : elle nous montre toujours la même face.'],
    en:['Why do we always see the same side of the Moon?', 'It spins once in the time it takes to go around the Earth', [['It does not spin at all', 'It does spin! Just at the same pace as its trip around the Earth, like a dancer who always faces you.'], ['The other side is in darkness forever', 'The far side gets sunshine too! We just cannot see it from here.']], 'The Moon spins once in about 27 days, the same time it takes to orbit the Earth, so it always shows us the same side.'],
    es:['¿Por qué vemos siempre la misma cara de la Luna?', 'Gira sobre sí misma en el mismo tiempo que tarda en dar la vuelta a la Tierra', [['No gira sobre sí misma', '¡Sí gira! Al mismo ritmo que su vuelta a la Tierra, como una bailarina que siempre te mira.'], ['La otra cara está siempre de noche', '¡La cara oculta también recibe Sol! Solo que no la vemos desde aquí.']], 'La Luna gira sobre sí misma en unos 27 días, lo mismo que tarda en dar la vuelta a la Tierra: siempre nos enseña la misma cara.'],
    de:['Warum sehen wir immer dieselbe Seite des Mondes?', 'Er dreht sich einmal um sich selbst, während er einmal um die Erde kreist', [['Er dreht sich gar nicht', 'Doch, er dreht sich! Nur im gleichen Takt wie seine Runde um die Erde, wie eine Tänzerin, die dich immer anschaut.'], ['Die andere Seite ist für immer dunkel', 'Die Rückseite bekommt auch Sonne! Wir sehen sie nur von hier aus nicht.']], 'Der Mond dreht sich in etwa 27 Tagen einmal um sich selbst, genauso lange wie eine Runde um die Erde: Deshalb zeigt er uns immer dieselbe Seite.'],
    it:['Perché vediamo sempre la stessa faccia della Luna?', 'Ruota su sé stessa nello stesso tempo in cui gira intorno alla Terra', [['Non ruota su sé stessa', 'Ruota eccome! Allo stesso ritmo del suo giro intorno alla Terra, come una ballerina che ti guarda sempre.'], ['L’altra faccia è sempre al buio', 'Anche la faccia nascosta prende il Sole! Solo che da qui non si vede.']], 'La Luna ruota su sé stessa in circa 27 giorni, lo stesso tempo del suo giro intorno alla Terra: ci mostra sempre la stessa faccia.'],
    pt:['Porque vemos sempre a mesma face da Lua?', 'Ela roda sobre si mesma no mesmo tempo que leva a dar a volta à Terra', [['Não roda sobre si mesma', 'Roda, sim! Ao mesmo ritmo da volta à Terra, como uma bailarina que olha sempre para ti.'], ['A outra face está sempre de noite', 'A face oculta também apanha Sol! Só não a vemos daqui.']], 'A Lua roda sobre si mesma em cerca de 27 dias, o mesmo tempo da sua volta à Terra: mostra-nos sempre a mesma face.']
  });
  P('etoile-filante', 'espace', {
    fr:['Une étoile filante, c’est…', 'Un petit caillou de l’espace qui brûle en entrant dans l’atmosphère', [['Une étoile qui tombe', 'Une étoile qui tombe ? Elle est des milliers de fois plus grosse que la Terre : on l’aurait remarquée. C’est un petit caillou.'], ['Un avion très rapide', 'Un avion ? Il clignote, lui, et il ne disparaît pas en une seconde. C’est un caillou qui brûle.']], 'Une étoile filante (météore) est un grain de poussière ou un caillou qui chauffe et brille en traversant l’atmosphère.'],
    en:['A shooting star is…', 'A small space rock burning up as it enters the atmosphere', [['A star that falls', 'A falling star? Stars are thousands of times bigger than the Earth: we would have noticed. It is a small rock.'], ['A very fast plane', 'A plane? Planes blink and do not vanish in one second. It is a rock burning up.']], 'A shooting star (meteor) is a speck of dust or a small rock that heats up and glows as it crosses the atmosphere.'],
    es:['Una estrella fugaz es…', 'Una piedrecita del espacio que arde al entrar en la atmósfera', [['Una estrella que se cae', '¿Una estrella que se cae? Es miles de veces más grande que la Tierra: lo habríamos notado. Es una piedrecita.'], ['Un avión muy rápido', '¿Un avión? Los aviones parpadean y no desaparecen en un segundo. Es una piedra que arde.']], 'Una estrella fugaz (meteoro) es un grano de polvo o una piedrecita que se calienta y brilla al cruzar la atmósfera.'],
    de:['Eine Sternschnuppe ist…', 'Ein kleiner Stein aus dem All, der beim Eintritt in die Atmosphäre verglüht', [['Ein Stern, der herunterfällt', 'Ein fallender Stern? Sterne sind tausendmal größer als die Erde: Das hätten wir gemerkt. Es ist ein kleiner Stein.'], ['Ein sehr schnelles Flugzeug', 'Ein Flugzeug? Das blinkt und verschwindet nicht in einer Sekunde. Es ist ein verglühender Stein.']], 'Eine Sternschnuppe (Meteor) ist ein Staubkorn oder kleiner Stein, der sich beim Flug durch die Atmosphäre erhitzt und leuchtet.'],
    it:['Una stella cadente è…', 'Un sassolino spaziale che brucia entrando nell’atmosfera', [['Una stella che cade', 'Una stella che cade? È migliaia di volte più grande della Terra: ce ne saremmo accorti. È un sassolino.'], ['Un aereo velocissimo', 'Un aereo? Gli aerei lampeggiano e non spariscono in un secondo. È un sasso che brucia.']], 'Una stella cadente (meteora) è un granello di polvere o un sassolino che si scalda e brilla attraversando l’atmosfera.'],
    pt:['Uma estrela cadente é…', 'Uma pedrinha do espaço que arde ao entrar na atmosfera', [['Uma estrela que cai', 'Uma estrela que cai? É milhares de vezes maior do que a Terra: teríamos reparado. É uma pedrinha.'], ['Um avião muito rápido', 'Um avião? Os aviões piscam e não desaparecem num segundo. É uma pedra a arder.']], 'Uma estrela cadente (meteoro) é um grão de poeira ou uma pedrinha que aquece e brilha ao atravessar a atmosfera.']
  });
  P('soleil-etoile', 'espace', {
    fr:['Le Soleil est…', 'Une étoile', [['Une planète', 'Une planète ? Les planètes tournent autour de LUI. Le Soleil est une étoile, et même la seule du système solaire.'], ['Un trou noir', 'Un trou noir ? Il nous éclaire tous les matins, ce serait gonflé pour un trou noir. C’est une étoile.']], 'Le Soleil est une étoile, une énorme boule de gaz très chaud. Les planètes tournent autour de lui.'],
    en:['The Sun is…', 'A star', [['A planet', 'A planet? The planets go around IT. The Sun is a star, the only one in the solar system.'], ['A black hole', 'A black hole? It lights up every morning, which would be cheeky for a black hole. It is a star.']], 'The Sun is a star, a huge ball of very hot gas. The planets go around it.'],
    es:['El Sol es…', 'Una estrella', [['Un planeta', '¿Un planeta? Los planetas giran alrededor de ÉL. El Sol es una estrella, la única del sistema solar.'], ['Un agujero negro', '¿Un agujero negro? Nos ilumina cada mañana, mucho morro para un agujero negro. Es una estrella.']], 'El Sol es una estrella, una enorme bola de gas muy caliente. Los planetas giran a su alrededor.'],
    de:['Die Sonne ist…', 'Ein Stern', [['Ein Planet', 'Ein Planet? Die Planeten kreisen um SIE. Die Sonne ist ein Stern, der einzige im Sonnensystem.'], ['Ein Schwarzes Loch', 'Ein Schwarzes Loch? Sie macht jeden Morgen hell, ganz schön frech für ein Schwarzes Loch. Es ist ein Stern.']], 'Die Sonne ist ein Stern, eine riesige Kugel aus sehr heißem Gas. Die Planeten kreisen um sie.'],
    it:['Il Sole è…', 'Una stella', [['Un pianeta', 'Un pianeta? Sono i pianeti a girargli intorno. Il Sole è una stella, l’unica del sistema solare.'], ['Un buco nero', 'Un buco nero? Ci illumina ogni mattina, bella faccia tosta per un buco nero. È una stella.']], 'Il Sole è una stella, un’enorme palla di gas caldissimo. I pianeti gli girano intorno.'],
    pt:['O Sol é…', 'Uma estrela', [['Um planeta', 'Um planeta? São os planetas que andam à volta DELE. O Sol é uma estrela, a única do sistema solar.'], ['Um buraco negro', 'Um buraco negro? Ilumina-nos todas as manhãs, que lata para um buraco negro. É uma estrela.']], 'O Sol é uma estrela, uma enorme bola de gás muito quente. Os planetas andam à volta dele.']
  });
  P('voie-lactee', 'espace', {
    fr:['Comment s’appelle notre galaxie ?', 'La Voie lactée', [['Andromède', 'Andromède, c’est la galaxie VOISINE. Tu as donné l’adresse du voisin. Nous, c’est la Voie lactée.'], ['La Grande Ourse', 'La Grande Ourse est une constellation, un dessin d’étoiles dans le ciel, pas une galaxie. Réponse : la Voie lactée.']], 'Notre galaxie, la Voie lactée, contient des centaines de milliards d’étoiles ; le Soleil n’est que l’une d’elles.'],
    en:['What is our galaxy called?', 'The Milky Way', [['Andromeda', 'Andromeda is the NEIGHBOURING galaxy. You gave the neighbour’s address. Ours is the Milky Way.'], ['The Great Bear', 'The Great Bear is a constellation, a pattern of stars in the sky, not a galaxy. Answer: the Milky Way.']], 'Our galaxy, the Milky Way, holds hundreds of billions of stars; the Sun is just one of them.'],
    es:['¿Cómo se llama nuestra galaxia?', 'La Vía Láctea', [['Andrómeda', 'Andrómeda es la galaxia VECINA. Has dado la dirección del vecino. La nuestra es la Vía Láctea.'], ['La Osa Mayor', 'La Osa Mayor es una constelación, un dibujo de estrellas en el cielo, no una galaxia. Respuesta: la Vía Láctea.']], 'Nuestra galaxia, la Vía Láctea, tiene cientos de miles de millones de estrellas; el Sol es solo una de ellas.'],
    de:['Wie heißt unsere Galaxie?', 'Die Milchstraße', [['Andromeda', 'Andromeda ist die NACHBAR-Galaxie. Du hast die Adresse vom Nachbarn genannt. Unsere ist die Milchstraße.'], ['Der Große Bär', 'Der Große Bär ist ein Sternbild am Himmel, keine Galaxie. Antwort: die Milchstraße.']], 'Unsere Galaxie, die Milchstraße, hat Hunderte Milliarden Sterne; die Sonne ist nur einer davon.'],
    it:['Come si chiama la nostra galassia?', 'La Via Lattea', [['Andromeda', 'Andromeda è la galassia VICINA. Hai dato l’indirizzo del vicino. La nostra è la Via Lattea.'], ['L’Orsa Maggiore', 'L’Orsa Maggiore è una costellazione, un disegno di stelle nel cielo, non una galassia. Risposta: la Via Lattea.']], 'La nostra galassia, la Via Lattea, contiene centinaia di miliardi di stelle; il Sole è solo una di esse.'],
    pt:['Como se chama a nossa galáxia?', 'A Via Láctea', [['Andrómeda', 'Andrómeda é a galáxia VIZINHA. Deste a morada do vizinho. A nossa é a Via Láctea.'], ['A Ursa Maior', 'A Ursa Maior é uma constelação, um desenho de estrelas no céu, não uma galáxia. Resposta: a Via Láctea.']], 'A nossa galáxia, a Via Láctea, tem centenas de milhares de milhões de estrelas; o Sol é apenas uma delas.']
  });
  P('pas-lune', 'espace', {
    fr:['Pourquoi les traces de pas des astronautes sont-elles encore sur la Lune ?', 'Il n’y a ni vent ni pluie pour les effacer', [['Quelqu’un les repasse au feutre', 'Un gardien de traces de pas ? Joli métier, mais il n’existe pas. Sans vent ni pluie, rien ne les efface.'], ['Le sol de la Lune est en ciment', 'Du ciment ? La Lune n’est pas un chantier. C’est une poussière fine, et rien ne vient la balayer.']], 'La Lune n’a presque pas d’atmosphère : pas de vent, pas de pluie. Les traces laissées depuis 1969 peuvent rester très longtemps.'],
    en:['Why are the astronauts’ footprints still on the Moon?', 'There is no wind or rain to wipe them away', [['Someone traces over them with a pen', 'A footprint keeper? Nice job, but it does not exist. With no wind or rain, nothing wipes them away.'], ['The Moon’s ground is made of cement', 'Cement? The Moon is not a building site. It is fine dust, and nothing comes to sweep it.']], 'The Moon has almost no atmosphere: no wind, no rain. Footprints left since 1969 can stay for a very long time.'],
    es:['¿Por qué siguen en la Luna las huellas de los astronautas?', 'No hay viento ni lluvia que las borre', [['Alguien las repasa con rotulador', '¿Un guardián de huellas? Bonito oficio, pero no existe. Sin viento ni lluvia, nada las borra.'], ['El suelo de la Luna es de cemento', '¿Cemento? La Luna no es una obra. Es un polvo fino, y nada viene a barrerlo.']], 'La Luna casi no tiene atmósfera: ni viento ni lluvia. Las huellas dejadas desde 1969 pueden quedarse muchísimo tiempo.'],
    de:['Warum sind die Fußspuren der Astronauten immer noch auf dem Mond?', 'Es gibt keinen Wind und keinen Regen, der sie verwischt', [['Jemand zeichnet sie mit Filzstift nach', 'Ein Fußspuren-Wächter? Schöner Beruf, aber den gibt es nicht. Ohne Wind und Regen verwischt nichts sie.'], ['Der Mondboden ist aus Zement', 'Zement? Der Mond ist keine Baustelle. Es ist feiner Staub, und nichts fegt ihn weg.']], 'Der Mond hat fast keine Atmosphäre: kein Wind, kein Regen. Spuren von 1969 können sehr lange bleiben.'],
    it:['Perché le impronte degli astronauti sono ancora sulla Luna?', 'Non c’è vento né pioggia a cancellarle', [['Qualcuno le ripassa col pennarello', 'Un custode delle impronte? Bel mestiere, ma non esiste. Senza vento né pioggia, niente le cancella.'], ['Il suolo della Luna è di cemento', 'Cemento? La Luna non è un cantiere. È una polvere fine, e niente viene a spazzarla.']], 'La Luna non ha quasi atmosfera: niente vento, niente pioggia. Le impronte lasciate dal 1969 possono restare a lungo.'],
    pt:['Porque é que as pegadas dos astronautas ainda estão na Lua?', 'Não há vento nem chuva para as apagar', [['Alguém as repassa com marcador', 'Um guarda de pegadas? Bonita profissão, mas não existe. Sem vento nem chuva, nada as apaga.'], ['O chão da Lua é de cimento', 'Cimento? A Lua não é uma obra. É uma poeira fina, e nada a vem varrer.']], 'A Lua quase não tem atmosfera: nem vento, nem chuva. As pegadas deixadas desde 1969 podem ficar muito tempo.']
  });
  P('olympus', 'espace', {
    fr:['Quel est le plus haut volcan connu du système solaire ?', 'Olympus Mons, sur Mars', [['L’Everest', 'L’Everest n’est même pas un volcan ! Et avec ses 8,8 km, il serait un nain à côté d’Olympus Mons.'], ['L’Etna', 'L’Etna est le roi de l’Europe, mais dans le système solaire il fait figure de taupinière. Réponse : Olympus Mons, sur Mars.']], 'Olympus Mons, un volcan éteint de Mars, mesure plus de 20 km de haut : plus de deux fois l’Everest.'],
    en:['What is the tallest known volcano in the solar system?', 'Olympus Mons, on Mars', [['Mount Everest', 'Everest is not even a volcano! And at 8.8 km, it would look tiny next to Olympus Mons.'], ['Mount Etna', 'Etna rules Europe, but in the solar system it is a molehill. Answer: Olympus Mons, on Mars.']], 'Olympus Mons, an extinct volcano on Mars, is over 20 km high: more than twice the height of Everest.'],
    es:['¿Cuál es el volcán más alto conocido del sistema solar?', 'Olympus Mons, en Marte', [['El Everest', '¡El Everest ni siquiera es un volcán! Y con sus 8,8 km sería un enano al lado de Olympus Mons.'], ['El Etna', 'El Etna es el rey de Europa, pero en el sistema solar es una topera. Respuesta: Olympus Mons, en Marte.']], 'Olympus Mons, un volcán apagado de Marte, mide más de 20 km de altura: más del doble que el Everest.'],
    de:['Welcher ist der höchste bekannte Vulkan im Sonnensystem?', 'Olympus Mons auf dem Mars', [['Der Mount Everest', 'Der Everest ist nicht einmal ein Vulkan! Und mit 8,8 km wäre er neben Olympus Mons ein Zwerg.'], ['Der Ätna', 'Der Ätna ist der König Europas, aber im Sonnensystem ein Maulwurfshügel. Antwort: Olympus Mons auf dem Mars.']], 'Olympus Mons, ein erloschener Vulkan auf dem Mars, ist über 20 km hoch: mehr als doppelt so hoch wie der Everest.'],
    it:['Qual è il vulcano più alto conosciuto del sistema solare?', 'Olympus Mons, su Marte', [['L’Everest', 'L’Everest non è nemmeno un vulcano! E con i suoi 8,8 km sarebbe un nano accanto a Olympus Mons.'], ['L’Etna', 'L’Etna è il re d’Europa, ma nel sistema solare è una montagnola. Risposta: Olympus Mons, su Marte.']], 'Olympus Mons, un vulcano spento di Marte, è alto più di 20 km: più del doppio dell’Everest.'],
    pt:['Qual é o vulcão mais alto conhecido do sistema solar?', 'Olympus Mons, em Marte', [['O Evereste', 'O Evereste nem sequer é um vulcão! E com os seus 8,8 km seria um anão ao lado do Olympus Mons.'], ['O Etna', 'O Etna é o rei da Europa, mas no sistema solar é um montinho. Resposta: Olympus Mons, em Marte.']], 'O Olympus Mons, um vulcão extinto de Marte, tem mais de 20 km de altura: mais do dobro do Evereste.']
  });
  P('poids-lune', 'espace', {
    fr:['Sur la Lune, ton poids est…', 'Environ 6 fois plus faible que sur Terre', [['Le même que sur Terre', 'Le même ? Alors pourquoi les astronautes font des bonds de kangourou ? Sur la Lune, tu pèses environ 6 fois moins.'], ['6 fois plus grand', 'Six fois plus lourd ? Tu resterais collé au sol comme un chewing-gum. C’est l’inverse : 6 fois plus léger.']], 'La Lune attire environ 6 fois moins fort que la Terre. Ta masse ne change pas, mais ton poids est environ 6 fois plus faible.'],
    en:['On the Moon, your weight is…', 'About 6 times less than on Earth', [['The same as on Earth', 'The same? Then why do astronauts bounce like kangaroos? On the Moon you weigh about 6 times less.'], ['6 times more', 'Six times heavier? You would be stuck to the ground like chewing gum. It is the other way round: 6 times lighter.']], 'The Moon pulls about 6 times less strongly than the Earth. Your mass does not change, but your weight is about 6 times less.'],
    es:['En la Luna, tu peso es…', 'Unas 6 veces menor que en la Tierra', [['El mismo que en la Tierra', '¿El mismo? ¿Y por qué los astronautas dan saltos de canguro? En la Luna pesas unas 6 veces menos.'], ['6 veces mayor', '¿Seis veces más? Te quedarías pegado al suelo como un chicle. Es al revés: 6 veces menos.']], 'La Luna atrae unas 6 veces menos que la Tierra. Tu masa no cambia, pero tu peso es unas 6 veces menor.'],
    de:['Auf dem Mond ist dein Gewicht…', 'Etwa 6-mal kleiner als auf der Erde', [['Genauso groß wie auf der Erde', 'Genauso? Warum hüpfen Astronauten dann wie Kängurus? Auf dem Mond wiegst du etwa 6-mal weniger.'], ['6-mal größer', 'Sechsmal schwerer? Du würdest am Boden kleben wie ein Kaugummi. Umgekehrt: 6-mal leichter.']], 'Der Mond zieht etwa 6-mal schwächer als die Erde. Deine Masse bleibt gleich, aber dein Gewicht ist etwa 6-mal kleiner.'],
    it:['Sulla Luna, il tuo peso è…', 'Circa 6 volte minore che sulla Terra', [['Uguale a quello sulla Terra', 'Uguale? E allora perché gli astronauti saltano come canguri? Sulla Luna pesi circa 6 volte meno.'], ['6 volte maggiore', 'Sei volte più pesante? Resteresti incollato al suolo come una gomma da masticare. È il contrario: 6 volte più leggero.']], 'La Luna attira circa 6 volte meno della Terra. La tua massa non cambia, ma il tuo peso è circa 6 volte minore.'],
    pt:['Na Lua, o teu peso é…', 'Cerca de 6 vezes menor do que na Terra', [['Igual ao da Terra', 'Igual? Então porque é que os astronautas saltam como cangurus? Na Lua pesas cerca de 6 vezes menos.'], ['6 vezes maior', 'Seis vezes mais pesado? Ficavas colado ao chão como uma pastilha elástica. É ao contrário: 6 vezes mais leve.']], 'A Lua atrai cerca de 6 vezes menos do que a Terra. A tua massa não muda, mas o teu peso é cerca de 6 vezes menor.']
  });
  P('neptune', 'espace', {
    fr:['Quelle planète est la plus éloignée du Soleil ?', 'Neptune', [['Pluton', 'Pluton ? Elle n’est plus une planète depuis 2006, elle a été rétrogradée en planète naine. La dernière, c’est Neptune.'], ['Uranus', 'Uranus est avant-dernière : presque ! La plus lointaine, c’est Neptune.']], 'Neptune est la 8e et dernière planète, environ 30 fois plus loin du Soleil que la Terre.'],
    en:['Which planet is furthest from the Sun?', 'Neptune', [['Pluto', 'Pluto? It has not been a planet since 2006, it was downgraded to a dwarf planet. The last one is Neptune.'], ['Uranus', 'Uranus is second to last: so close! The furthest is Neptune.']], 'Neptune is the 8th and last planet, about 30 times further from the Sun than the Earth.'],
    es:['¿Qué planeta está más lejos del Sol?', 'Neptuno', [['Plutón', '¿Plutón? Dejó de ser planeta en 2006: ahora es planeta enano. El último es Neptuno.'], ['Urano', 'Urano es el penúltimo: ¡casi! El más lejano es Neptuno.']], 'Neptuno es el 8.º y último planeta, unas 30 veces más lejos del Sol que la Tierra.'],
    de:['Welcher Planet ist am weitesten von der Sonne entfernt?', 'Neptun', [['Pluto', 'Pluto? Seit 2006 kein Planet mehr, er wurde zum Zwergplaneten. Der letzte ist Neptun.'], ['Uranus', 'Uranus ist der vorletzte: knapp daneben! Am weitesten weg ist Neptun.']], 'Neptun ist der 8. und letzte Planet, etwa 30-mal weiter von der Sonne entfernt als die Erde.'],
    it:['Quale pianeta è il più lontano dal Sole?', 'Nettuno', [['Plutone', 'Plutone? Dal 2006 non è più un pianeta: è un pianeta nano. L’ultimo è Nettuno.'], ['Urano', 'Urano è il penultimo: quasi! Il più lontano è Nettuno.']], 'Nettuno è l’8º e ultimo pianeta, circa 30 volte più lontano dal Sole della Terra.'],
    pt:['Que planeta está mais longe do Sol?', 'Neptuno', [['Plutão', 'Plutão? Deixou de ser planeta em 2006: agora é planeta anão. O último é Neptuno.'], ['Úrano', 'Úrano é o penúltimo: quase! O mais distante é Neptuno.']], 'Neptuno é o 8.º e último planeta, cerca de 30 vezes mais longe do Sol do que a Terra.']
  });

  // ── 🚀 Fusées et astronautes ──
  P('spoutnik', 'fusees', {
    fr:['Quel a été le premier satellite artificiel, lancé en 1957 ?', 'Spoutnik 1', [['Apollo 11', 'Apollo 11, c’est 1969 et la Lune. Tu as douze ans d’avance ! Le premier satellite, c’est Spoutnik 1.'], ['Hubble', 'Hubble est un télescope lancé en 1990. Il est arrivé après la fête. Réponse : Spoutnik 1.']], 'Spoutnik 1, lancé par l’URSS le 4 octobre 1957, était une petite boule de métal qui émettait des « bips » radio.'],
    en:['What was the first artificial satellite, launched in 1957?', 'Sputnik 1', [['Apollo 11', 'Apollo 11 was 1969 and the Moon. You are twelve years early! The first satellite was Sputnik 1.'], ['Hubble', 'Hubble is a telescope launched in 1990. It arrived after the party. Answer: Sputnik 1.']], 'Sputnik 1, launched by the USSR on 4 October 1957, was a small metal ball that sent out radio beeps.'],
    es:['¿Cuál fue el primer satélite artificial, lanzado en 1957?', 'Sputnik 1', [['Apolo 11', 'El Apolo 11 fue en 1969 y a la Luna. ¡Llegas doce años antes! El primer satélite fue el Sputnik 1.'], ['Hubble', 'El Hubble es un telescopio lanzado en 1990. Llegó después de la fiesta. Respuesta: Sputnik 1.']], 'El Sputnik 1, lanzado por la URSS el 4 de octubre de 1957, era una pequeña bola de metal que emitía pitidos de radio.'],
    de:['Was war der erste künstliche Satellit, gestartet 1957?', 'Sputnik 1', [['Apollo 11', 'Apollo 11 war 1969 und der Mond. Du bist zwölf Jahre zu früh! Der erste Satellit war Sputnik 1.'], ['Hubble', 'Hubble ist ein Teleskop, gestartet 1990. Es kam nach der Party. Antwort: Sputnik 1.']], 'Sputnik 1, am 4. Oktober 1957 von der UdSSR gestartet, war eine kleine Metallkugel, die Funk-Pieptöne sendete.'],
    it:['Qual è stato il primo satellite artificiale, lanciato nel 1957?', 'Sputnik 1', [['Apollo 11', 'Apollo 11 è il 1969 e la Luna. Sei in anticipo di dodici anni! Il primo satellite è lo Sputnik 1.'], ['Hubble', 'Hubble è un telescopio lanciato nel 1990. È arrivato dopo la festa. Risposta: Sputnik 1.']], 'Lo Sputnik 1, lanciato dall’URSS il 4 ottobre 1957, era una pallina di metallo che emetteva bip radio.'],
    pt:['Qual foi o primeiro satélite artificial, lançado em 1957?', 'Sputnik 1', [['Apollo 11', 'A Apollo 11 foi em 1969 e à Lua. Estás doze anos adiantado! O primeiro satélite foi o Sputnik 1.'], ['Hubble', 'O Hubble é um telescópio lançado em 1990. Chegou depois da festa. Resposta: Sputnik 1.']], 'O Sputnik 1, lançado pela URSS a 4 de outubro de 1957, era uma pequena bola de metal que emitia bips de rádio.']
  });
  P('laika', 'fusees', {
    fr:['Quel animal célèbre a fait le tour de la Terre en 1957 ?', 'La chienne Laïka', [['Un hamster', 'Un hamster dans l’espace ? Il aurait fait sa roue en apesanteur. C’était la chienne Laïka.'], ['Un perroquet', 'Un perroquet ? Il aurait répété « décollage » pendant tout le vol. C’était la chienne Laïka.']], 'Laïka a été le premier animal mis en orbite, à bord de Spoutnik 2, en novembre 1957.'],
    en:['Which famous animal went around the Earth in 1957?', 'Laika the dog', [['A hamster', 'A hamster in space? It would have run its wheel in zero gravity. It was Laika the dog.'], ['A parrot', 'A parrot? It would have repeated “lift-off” the whole flight. It was Laika the dog.']], 'Laika was the first animal put into orbit, on board Sputnik 2, in November 1957.'],
    es:['¿Qué animal famoso dio la vuelta a la Tierra en 1957?', 'La perrita Laika', [['Un hámster', '¿Un hámster en el espacio? Habría hecho girar su rueda en ingravidez. Fue la perrita Laika.'], ['Un loro', '¿Un loro? Habría repetido «despegue» todo el vuelo. Fue la perrita Laika.']], 'Laika fue el primer animal puesto en órbita, a bordo del Sputnik 2, en noviembre de 1957.'],
    de:['Welches berühmte Tier umkreiste 1957 die Erde?', 'Die Hündin Laika', [['Ein Hamster', 'Ein Hamster im All? Er wäre in der Schwerelosigkeit im Laufrad gerannt. Es war die Hündin Laika.'], ['Ein Papagei', 'Ein Papagei? Er hätte den ganzen Flug „Start“ wiederholt. Es war die Hündin Laika.']], 'Laika war das erste Tier in einer Umlaufbahn, an Bord von Sputnik 2, im November 1957.'],
    it:['Quale animale famoso ha fatto il giro della Terra nel 1957?', 'La cagnolina Laika', [['Un criceto', 'Un criceto nello spazio? Avrebbe girato la ruota senza peso. Era la cagnolina Laika.'], ['Un pappagallo', 'Un pappagallo? Avrebbe ripetuto «decollo» per tutto il volo. Era la cagnolina Laika.']], 'Laika è stata il primo animale messo in orbita, a bordo dello Sputnik 2, nel novembre 1957.'],
    pt:['Que animal famoso deu a volta à Terra em 1957?', 'A cadela Laika', [['Um hamster', 'Um hamster no espaço? Teria rodado a roda sem gravidade. Foi a cadela Laika.'], ['Um papagaio', 'Um papagaio? Teria repetido «descolagem» o voo todo. Foi a cadela Laika.']], 'A Laika foi o primeiro animal posto em órbita, a bordo do Sputnik 2, em novembro de 1957.']
  });
  P('terechkova', 'fusees', {
    fr:['Qui a été la première femme dans l’espace, en 1963 ?', 'Valentina Terechkova', [['Marie Curie', 'Marie Curie, deux prix Nobel, mais jamais de fusée ! La première femme dans l’espace, c’est Valentina Terechkova.'], ['Claudie Haigneré', 'Claudie Haigneré est la première FRANÇAISE dans l’espace, en 1996. La toute première femme : Valentina Terechkova, en 1963.']], 'La Soviétique Valentina Terechkova a fait 48 fois le tour de la Terre en juin 1963.'],
    en:['Who was the first woman in space, in 1963?', 'Valentina Tereshkova', [['Marie Curie', 'Marie Curie won two Nobel Prizes, but never took a rocket! The first woman in space was Valentina Tereshkova.'], ['Helen Sharman', 'Helen Sharman was the first BRITISH astronaut, in 1991. The very first woman: Valentina Tereshkova, in 1963.']], 'Soviet cosmonaut Valentina Tereshkova went around the Earth 48 times in June 1963.'],
    es:['¿Quién fue la primera mujer en el espacio, en 1963?', 'Valentina Tereshkova', [['Marie Curie', 'Marie Curie ganó dos premios Nobel, ¡pero nunca subió a un cohete! La primera mujer en el espacio fue Valentina Tereshkova.'], ['Sally Ride', 'Sally Ride fue la primera ESTADOUNIDENSE, en 1983. La primerísima: Valentina Tereshkova, en 1963.']], 'La soviética Valentina Tereshkova dio 48 vueltas a la Tierra en junio de 1963.'],
    de:['Wer war 1963 die erste Frau im All?', 'Valentina Tereschkowa', [['Marie Curie', 'Marie Curie hat zwei Nobelpreise, ist aber nie Rakete geflogen! Die erste Frau im All war Valentina Tereschkowa.'], ['Sally Ride', 'Sally Ride war 1983 die erste AMERIKANERIN im All. Die allererste Frau: Valentina Tereschkowa, 1963.']], 'Die sowjetische Kosmonautin Valentina Tereschkowa umkreiste im Juni 1963 die Erde 48-mal.'],
    it:['Chi è stata la prima donna nello spazio, nel 1963?', 'Valentina Tereshkova', [['Marie Curie', 'Marie Curie ha vinto due Nobel, ma non è mai salita su un razzo! La prima donna nello spazio è Valentina Tereshkova.'], ['Samantha Cristoforetti', 'Samantha Cristoforetti è stata la prima ITALIANA nello spazio, nel 2014. La primissima: Valentina Tereshkova, nel 1963.']], 'La sovietica Valentina Tereshkova ha fatto 48 giri della Terra nel giugno 1963.'],
    pt:['Quem foi a primeira mulher no espaço, em 1963?', 'Valentina Tereshkova', [['Marie Curie', 'Marie Curie ganhou dois prémios Nobel, mas nunca andou de foguetão! A primeira mulher no espaço foi Valentina Tereshkova.'], ['Sally Ride', 'Sally Ride foi a primeira AMERICANA, em 1983. A primeiríssima: Valentina Tereshkova, em 1963.']], 'A soviética Valentina Tereshkova deu 48 voltas à Terra em junho de 1963.']
  });
  P('apollo11', 'fusees', {
    fr:['Comment s’appelait la mission qui a posé les premiers humains sur la Lune ?', 'Apollo 11', [['Spoutnik', 'Spoutnik était un satellite sans passager, en 1957. Pas de pas sur la Lune ! C’était Apollo 11.'], ['Ariane 5', 'Ariane 5 est une fusée européenne qui n’a jamais emmené d’humains. La mission lunaire, c’est Apollo 11.']], 'En juillet 1969, la mission américaine Apollo 11 a posé Neil Armstrong et Buzz Aldrin sur la Lune.'],
    en:['What was the mission that first landed humans on the Moon called?', 'Apollo 11', [['Sputnik', 'Sputnik was a satellite with no passengers, in 1957. No steps on the Moon! It was Apollo 11.'], ['Ariane 5', 'Ariane 5 is a European rocket that never carried humans. The Moon mission was Apollo 11.']], 'In July 1969, the American Apollo 11 mission landed Neil Armstrong and Buzz Aldrin on the Moon.'],
    es:['¿Cómo se llamaba la misión que llevó a los primeros humanos a la Luna?', 'Apolo 11', [['Sputnik', 'El Sputnik era un satélite sin pasajeros, en 1957. ¡Ni un paso en la Luna! Fue el Apolo 11.'], ['Ariane 5', 'El Ariane 5 es un cohete europeo que nunca ha llevado humanos. La misión lunar fue el Apolo 11.']], 'En julio de 1969, la misión estadounidense Apolo 11 llevó a Neil Armstrong y Buzz Aldrin a la Luna.'],
    de:['Wie hieß die Mission, die zum ersten Mal Menschen auf den Mond brachte?', 'Apollo 11', [['Sputnik', 'Sputnik war 1957 ein Satellit ohne Passagiere. Kein Schritt auf dem Mond! Es war Apollo 11.'], ['Ariane 5', 'Ariane 5 ist eine europäische Rakete, die nie Menschen mitgenommen hat. Die Mondmission war Apollo 11.']], 'Im Juli 1969 brachte die amerikanische Mission Apollo 11 Neil Armstrong und Buzz Aldrin auf den Mond.'],
    it:['Come si chiamava la missione che portò i primi esseri umani sulla Luna?', 'Apollo 11', [['Sputnik', 'Lo Sputnik era un satellite senza passeggeri, nel 1957. Nessun passo sulla Luna! Era l’Apollo 11.'], ['Ariane 5', 'Ariane 5 è un razzo europeo che non ha mai portato esseri umani. La missione lunare è l’Apollo 11.']], 'Nel luglio 1969 la missione americana Apollo 11 portò Neil Armstrong e Buzz Aldrin sulla Luna.'],
    pt:['Como se chamava a missão que levou os primeiros humanos à Lua?', 'Apollo 11', [['Sputnik', 'O Sputnik era um satélite sem passageiros, em 1957. Nem um passo na Lua! Foi a Apollo 11.'], ['Ariane 5', 'O Ariane 5 é um foguetão europeu que nunca levou humanos. A missão lunar foi a Apollo 11.']], 'Em julho de 1969, a missão americana Apollo 11 levou Neil Armstrong e Buzz Aldrin à Lua.']
  });
  P('hubble', 'fusees', {
    fr:['Où se trouve le télescope spatial Hubble ?', 'En orbite autour de la Terre', [['Sur la Lune', 'Sur la Lune ? Personne n’est allé l’y installer. Hubble tourne autour de la Terre, à environ 540 km.'], ['Au sommet de la tour Eiffel', 'La tour Eiffel a une belle vue, mais pas sur les galaxies ! Hubble est en orbite autour de la Terre.']], 'Lancé en 1990, Hubble tourne au-dessus de l’atmosphère, qui brouille les images : il voit l’espace bien plus net.'],
    en:['Where is the Hubble Space Telescope?', 'In orbit around the Earth', [['On the Moon', 'On the Moon? Nobody went there to set it up. Hubble goes around the Earth, about 540 km up.'], ['On top of Big Ben', 'Big Ben has a nice view, but not of galaxies! Hubble is in orbit around the Earth.']], 'Launched in 1990, Hubble orbits above the atmosphere, which blurs images, so it sees space much more clearly.'],
    es:['¿Dónde está el telescopio espacial Hubble?', 'En órbita alrededor de la Tierra', [['En la Luna', '¿En la Luna? Nadie fue a instalarlo allí. El Hubble gira alrededor de la Tierra, a unos 540 km.'], ['En lo alto de la Giralda', 'La Giralda tiene buenas vistas, ¡pero no de galaxias! El Hubble está en órbita alrededor de la Tierra.']], 'Lanzado en 1990, el Hubble gira por encima de la atmósfera, que emborrona las imágenes: ve el espacio mucho más nítido.'],
    de:['Wo befindet sich das Weltraumteleskop Hubble?', 'In einer Umlaufbahn um die Erde', [['Auf dem Mond', 'Auf dem Mond? Niemand hat es dort aufgebaut. Hubble kreist in etwa 540 km Höhe um die Erde.'], ['Auf dem Kölner Dom', 'Der Kölner Dom hat eine schöne Aussicht, aber nicht auf Galaxien! Hubble kreist um die Erde.']], 'Hubble wurde 1990 gestartet und kreist über der Atmosphäre, die Bilder verschwimmen lässt: So sieht es das All viel schärfer.'],
    it:['Dove si trova il telescopio spaziale Hubble?', 'In orbita intorno alla Terra', [['Sulla Luna', 'Sulla Luna? Nessuno è andato a montarlo lì. Hubble gira intorno alla Terra, a circa 540 km.'], ['In cima al Colosseo', 'Il Colosseo ha una bella vista, ma non sulle galassie! Hubble è in orbita intorno alla Terra.']], 'Lanciato nel 1990, Hubble gira sopra l’atmosfera, che sfoca le immagini: vede lo spazio molto più nitido.'],
    pt:['Onde está o telescópio espacial Hubble?', 'Em órbita à volta da Terra', [['Na Lua', 'Na Lua? Ninguém foi lá montá-lo. O Hubble anda à volta da Terra, a cerca de 540 km.'], ['No topo da Torre de Belém', 'A Torre de Belém tem boa vista, mas não para galáxias! O Hubble está em órbita à volta da Terra.']], 'Lançado em 1990, o Hubble anda acima da atmosfera, que desfoca as imagens: vê o espaço muito mais nítido.']
  });
  P('gps', 'fusees', {
    fr:['À quoi servent les satellites GPS ?', 'À se repérer sur Terre', [['À observer les autres galaxies', 'Ça, c’est le travail des télescopes. Les satellites GPS regardent vers nous pour dire où on est.'], ['À réchauffer la Terre', 'Un radiateur en orbite ? Le Soleil fait ça très bien tout seul. Les GPS servent à se repérer.']], 'Une trentaine de satellites GPS envoient des signaux ; ton téléphone compare leurs signaux pour calculer ta position.'],
    en:['What are GPS satellites for?', 'Finding your position on Earth', [['Watching other galaxies', 'That is a telescope’s job. GPS satellites look towards us to tell us where we are.'], ['Warming up the Earth', 'A heater in orbit? The Sun does that very well on its own. GPS is for finding your way.']], 'About thirty GPS satellites send signals; your phone compares them to work out where you are.'],
    es:['¿Para qué sirven los satélites GPS?', 'Para situarse en la Tierra', [['Para observar otras galaxias', 'Eso es trabajo de los telescopios. Los satélites GPS miran hacia nosotros para decir dónde estamos.'], ['Para calentar la Tierra', '¿Un radiador en órbita? El Sol lo hace muy bien solito. El GPS sirve para orientarse.']], 'Una treintena de satélites GPS envían señales; tu móvil las compara para calcular tu posición.'],
    de:['Wofür sind GPS-Satelliten da?', 'Um auf der Erde den eigenen Standort zu finden', [['Um andere Galaxien zu beobachten', 'Das machen Teleskope. GPS-Satelliten schauen zu uns, um zu sagen, wo wir sind.'], ['Um die Erde zu wärmen', 'Eine Heizung im All? Das macht die Sonne schon ganz allein. GPS dient zur Orientierung.']], 'Rund dreißig GPS-Satelliten senden Signale; dein Handy vergleicht sie und berechnet deinen Standort.'],
    it:['A che cosa servono i satelliti GPS?', 'A orientarsi sulla Terra', [['A osservare altre galassie', 'Quello è il lavoro dei telescopi. I satelliti GPS guardano verso di noi per dire dove siamo.'], ['A scaldare la Terra', 'Un termosifone in orbita? Il Sole lo fa benissimo da solo. Il GPS serve a orientarsi.']], 'Una trentina di satelliti GPS inviano segnali; il tuo telefono li confronta per calcolare la tua posizione.'],
    pt:['Para que servem os satélites GPS?', 'Para nos orientarmos na Terra', [['Para observar outras galáxias', 'Isso é trabalho dos telescópios. Os satélites GPS olham para nós para dizer onde estamos.'], ['Para aquecer a Terra', 'Um aquecedor em órbita? O Sol faz isso muito bem sozinho. O GPS serve para nos orientarmos.']], 'Cerca de trinta satélites GPS enviam sinais; o teu telemóvel compara-os para calcular a tua posição.']
  });
  P('carburant', 'fusees', {
    fr:['Pourquoi les fusées sont-elles si grandes au décollage ?', 'Elles emportent énormément de carburant', [['Pour qu’on les voie de loin', 'Pour la frime ? Une fusée n’est pas un panneau publicitaire. L’essentiel de sa taille, ce sont ses réservoirs.'], ['Pour loger des centaines de passagers', 'Des centaines ? La capsule n’accueille que quelques astronautes. Le reste, c’est du carburant.']], 'Pour échapper à l’attraction de la Terre, une fusée brûle des tonnes de carburant : ses réservoirs prennent presque toute la place.'],
    en:['Why are rockets so big at lift-off?', 'They carry a huge amount of fuel', [['So people can see them from far away', 'To show off? A rocket is not a billboard. Most of its size is fuel tanks.'], ['To fit hundreds of passengers', 'Hundreds? The capsule only holds a few astronauts. The rest is fuel.']], 'To escape the Earth’s pull, a rocket burns tonnes of fuel: its tanks take up almost all the space.'],
    es:['¿Por qué los cohetes son tan grandes al despegar?', 'Llevan muchísimo combustible', [['Para que se vean de lejos', '¿Para presumir? Un cohete no es un cartel publicitario. Casi todo su tamaño son depósitos.'], ['Para llevar cientos de pasajeros', '¿Cientos? La cápsula solo lleva a unos pocos astronautas. El resto es combustible.']], 'Para escapar de la atracción de la Tierra, un cohete quema toneladas de combustible: sus depósitos ocupan casi todo el espacio.'],
    de:['Warum sind Raketen beim Start so groß?', 'Sie haben riesige Mengen Treibstoff dabei', [['Damit man sie von weitem sieht', 'Zum Angeben? Eine Rakete ist keine Werbetafel. Fast ihre ganze Größe sind Tanks.'], ['Für Hunderte Passagiere', 'Hunderte? In der Kapsel sitzen nur ein paar Astronauten. Der Rest ist Treibstoff.']], 'Um der Anziehung der Erde zu entkommen, verbrennt eine Rakete tonnenweise Treibstoff: Ihre Tanks nehmen fast den ganzen Platz ein.'],
    it:['Perché i razzi sono così grandi al decollo?', 'Trasportano moltissimo carburante', [['Per farsi vedere da lontano', 'Per fare scena? Un razzo non è un cartellone pubblicitario. Quasi tutta la sua altezza sono serbatoi.'], ['Per ospitare centinaia di passeggeri', 'Centinaia? La capsula ospita solo pochi astronauti. Il resto è carburante.']], 'Per sfuggire all’attrazione della Terra, un razzo brucia tonnellate di carburante: i serbatoi occupano quasi tutto lo spazio.'],
    pt:['Porque é que os foguetões são tão grandes na descolagem?', 'Levam imenso combustível', [['Para se verem de longe', 'Para se exibirem? Um foguetão não é um painel publicitário. Quase todo o tamanho são depósitos.'], ['Para levar centenas de passageiros', 'Centenas? A cápsula só leva alguns astronautas. O resto é combustível.']], 'Para escapar à atração da Terra, um foguetão queima toneladas de combustível: os depósitos ocupam quase todo o espaço.']
  });
  P('etages', 'fusees', {
    fr:['Pourquoi une fusée lâche-t-elle des morceaux (ses étages) en montant ?', 'Pour se débarrasser des réservoirs vides et être plus légère', [['Elle se casse, c’est normal', 'Elle ne se casse pas, elle fait du tri ! Les étages vides sont lâchés exprès pour l’alléger.'], ['Pour faire joli dans le ciel', 'Un spectacle ? C’est surtout de la physique : moins de poids, moins de carburant à brûler.']], 'Une fois vide, un étage n’est plus qu’un poids mort : la fusée le largue pour aller plus loin avec moins de carburant.'],
    en:['Why does a rocket drop parts (its stages) as it climbs?', 'To get rid of empty tanks and be lighter', [['It breaks, that is normal', 'It does not break, it tidies up! Empty stages are dropped on purpose to make it lighter.'], ['To look nice in the sky', 'A show? It is mostly physics: less weight, less fuel to burn.']], 'Once empty, a stage is just dead weight: the rocket drops it to go further with less fuel.'],
    es:['¿Por qué un cohete suelta piezas (sus etapas) al subir?', 'Para deshacerse de los depósitos vacíos y ser más ligero', [['Se rompe, es normal', '¡No se rompe, hace limpieza! Las etapas vacías se sueltan a propósito para aligerarlo.'], ['Para quedar bonito en el cielo', '¿Un espectáculo? Es sobre todo física: menos peso, menos combustible que quemar.']], 'Una vez vacía, una etapa es solo peso muerto: el cohete la suelta para llegar más lejos con menos combustible.'],
    de:['Warum wirft eine Rakete beim Aufstieg Teile (ihre Stufen) ab?', 'Um leere Tanks loszuwerden und leichter zu werden', [['Sie geht kaputt, das ist normal', 'Sie geht nicht kaputt, sie räumt auf! Leere Stufen werden absichtlich abgeworfen, damit sie leichter wird.'], ['Damit es am Himmel schön aussieht', 'Eine Show? Das ist vor allem Physik: weniger Gewicht, weniger Treibstoff.']], 'Eine leere Stufe ist nur totes Gewicht: Die Rakete wirft sie ab, um mit weniger Treibstoff weiterzukommen.'],
    it:['Perché un razzo sgancia dei pezzi (i suoi stadi) mentre sale?', 'Per liberarsi dei serbatoi vuoti ed essere più leggero', [['Si rompe, è normale', 'Non si rompe, fa ordine! Gli stadi vuoti vengono sganciati apposta per alleggerirlo.'], ['Per fare scena nel cielo', 'Uno spettacolo? È soprattutto fisica: meno peso, meno carburante da bruciare.']], 'Una volta vuoto, uno stadio è solo peso morto: il razzo lo sgancia per andare più lontano con meno carburante.'],
    pt:['Porque é que um foguetão larga peças (os seus andares) ao subir?', 'Para se livrar dos depósitos vazios e ficar mais leve', [['Parte-se, é normal', 'Não se parte, arruma-se! Os andares vazios são largados de propósito para o aliviar.'], ['Para ficar bonito no céu', 'Um espetáculo? É sobretudo física: menos peso, menos combustível a queimar.']], 'Depois de vazio, um andar é só peso morto: o foguetão larga-o para ir mais longe com menos combustível.']
  });
  P('rover', 'fusees', {
    fr:['Comment explore-t-on Mars aujourd’hui, sans astronautes ?', 'Avec des robots roulants, les rovers', [['Personne ne l’explore', 'Personne ? Des robots s’y baladent depuis des années ! Curiosity et Perseverance roulent sur Mars.'], ['Avec des plongeurs', 'Des plongeurs ? Il n’y a pas d’océan liquide à la surface de Mars. On y envoie des rovers.']], 'Des robots comme Curiosity (2012) et Perseverance (2021) roulent sur Mars, prennent des photos et analysent les roches.'],
    en:['How do we explore Mars today, without astronauts?', 'With wheeled robots called rovers', [['Nobody explores it', 'Nobody? Robots have been driving around there for years! Curiosity and Perseverance roll across Mars.'], ['With divers', 'Divers? There is no liquid ocean on the surface of Mars. We send rovers.']], 'Robots such as Curiosity (2012) and Perseverance (2021) drive on Mars, take photos and study the rocks.'],
    es:['¿Cómo se explora hoy Marte, sin astronautas?', 'Con robots con ruedas, los rovers', [['Nadie lo explora', '¿Nadie? ¡Hay robots paseando por allí desde hace años! Curiosity y Perseverance ruedan por Marte.'], ['Con buzos', '¿Buzos? En la superficie de Marte no hay océanos líquidos. Se envían rovers.']], 'Robots como Curiosity (2012) y Perseverance (2021) ruedan por Marte, toman fotos y analizan las rocas.'],
    de:['Wie erforscht man den Mars heute ohne Astronauten?', 'Mit fahrenden Robotern, den Rovern', [['Niemand erforscht ihn', 'Niemand? Dort fahren seit Jahren Roboter herum! Curiosity und Perseverance rollen über den Mars.'], ['Mit Tauchern', 'Taucher? Auf der Marsoberfläche gibt es keinen flüssigen Ozean. Man schickt Rover.']], 'Roboter wie Curiosity (2012) und Perseverance (2021) fahren über den Mars, machen Fotos und untersuchen Gestein.'],
    it:['Come si esplora oggi Marte, senza astronauti?', 'Con robot su ruote, i rover', [['Nessuno lo esplora', 'Nessuno? Lì girano robot da anni! Curiosity e Perseverance viaggiano su Marte.'], ['Con dei sub', 'Dei sub? Sulla superficie di Marte non c’è un oceano liquido. Si mandano i rover.']], 'Robot come Curiosity (2012) e Perseverance (2021) viaggiano su Marte, scattano foto e analizzano le rocce.'],
    pt:['Como se explora hoje Marte, sem astronautas?', 'Com robôs com rodas, os rovers', [['Ninguém o explora', 'Ninguém? Há robôs a passear por lá há anos! O Curiosity e o Perseverance andam por Marte.'], ['Com mergulhadores', 'Mergulhadores? Não há oceano líquido à superfície de Marte. Enviam-se rovers.']], 'Robôs como o Curiosity (2012) e o Perseverance (2021) andam por Marte, tiram fotos e analisam as rochas.']
  });
  P('miettes', 'fusees', {
    fr:['Dans la station spatiale, pourquoi les miettes sont-elles un problème ?', 'Elles flottent et peuvent se glisser dans les appareils', [['Elles attirent des fourmis de l’espace', 'Des fourmis de l’espace ? Joli film, mais non. Les miettes flottent et vont se coincer partout.'], ['Elles tombent trop vite', 'Tomber ? En apesanteur, rien ne tombe au sol : les miettes flottent et filent dans les machines.']], 'En apesanteur, une miette flotte : elle peut se coincer dans un appareil ou être respirée. Les astronautes mangent des aliments qui s’émiettent peu.'],
    en:['In the space station, why are crumbs a problem?', 'They float and can get into the equipment', [['They attract space ants', 'Space ants? Nice film idea, but no. Crumbs float and get stuck everywhere.'], ['They fall too fast', 'Fall? In zero gravity nothing drops to the floor: crumbs float into the machines.']], 'In zero gravity a crumb floats: it can get stuck in equipment or be breathed in. Astronauts eat food that does not crumble much.'],
    es:['En la estación espacial, ¿por qué las migas son un problema?', 'Flotan y pueden colarse en los aparatos', [['Atraen hormigas espaciales', '¿Hormigas espaciales? Buena idea para una película, pero no. Las migas flotan y se meten por todas partes.'], ['Caen demasiado rápido', '¿Caer? En ingravidez nada cae al suelo: las migas flotan y se cuelan en las máquinas.']], 'En ingravidez, una miga flota: puede atascarse en un aparato o respirarse. Los astronautas comen alimentos que se desmigajan poco.'],
    de:['Warum sind Krümel in der Raumstation ein Problem?', 'Sie schweben und können in die Geräte gelangen', [['Sie locken Weltraum-Ameisen an', 'Weltraum-Ameisen? Gute Filmidee, aber nein. Krümel schweben und bleiben überall hängen.'], ['Sie fallen zu schnell', 'Fallen? In der Schwerelosigkeit fällt nichts auf den Boden: Krümel schweben in die Maschinen.']], 'In der Schwerelosigkeit schwebt ein Krümel: Er kann in einem Gerät stecken bleiben oder eingeatmet werden. Astronauten essen Lebensmittel, die kaum krümeln.'],
    it:['Nella stazione spaziale, perché le briciole sono un problema?', 'Galleggiano e possono infilarsi negli apparecchi', [['Attirano formiche spaziali', 'Formiche spaziali? Bell’idea per un film, ma no. Le briciole galleggiano e si infilano ovunque.'], ['Cadono troppo in fretta', 'Cadere? Senza peso niente cade a terra: le briciole galleggiano dentro le macchine.']], 'Senza peso una briciola galleggia: può incastrarsi in un apparecchio o essere respirata. Gli astronauti mangiano cibi che si sbriciolano poco.'],
    pt:['Na estação espacial, porque é que as migalhas são um problema?', 'Flutuam e podem entrar nos aparelhos', [['Atraem formigas espaciais', 'Formigas espaciais? Boa ideia para um filme, mas não. As migalhas flutuam e metem-se em todo o lado.'], ['Caem depressa demais', 'Cair? Sem gravidade nada cai ao chão: as migalhas flutuam para dentro das máquinas.']], 'Sem gravidade, uma migalha flutua: pode ficar presa num aparelho ou ser respirada. Os astronautas comem alimentos que se desfazem pouco.']
  });

  // ── 🫀 Corps humain ──
  P('coeur-bat', 'corps', {
    fr:['Au repos, combien de fois environ le cœur d’un adulte bat-il par minute ?', 'Entre 60 et 100 fois', [['Environ 5 fois', 'Cinq battements par minute ? Ton cœur ferait la sieste. Au repos, c’est entre 60 et 100.'], ['Environ 1 000 fois', 'Mille ? Ce serait un colibri, pas un humain ! Au repos, c’est entre 60 et 100 battements.']], 'Au repos, le cœur d’un adulte bat environ 60 à 100 fois par minute ; il accélère pendant l’effort.'],
    en:['At rest, roughly how many times does an adult’s heart beat per minute?', 'Between 60 and 100 times', [['About 5 times', 'Five beats a minute? Your heart would be taking a nap. At rest, it is 60 to 100.'], ['About 1,000 times', 'A thousand? That is a hummingbird, not a human! At rest, it is 60 to 100 beats.']], 'At rest, an adult’s heart beats about 60 to 100 times a minute; it speeds up during exercise.'],
    es:['En reposo, ¿cuántas veces late más o menos el corazón de un adulto por minuto?', 'Entre 60 y 100 veces', [['Unas 5 veces', '¿Cinco latidos por minuto? Tu corazón estaría echando la siesta. En reposo son entre 60 y 100.'], ['Unas 1000 veces', '¿Mil? ¡Eso es un colibrí, no un humano! En reposo son entre 60 y 100 latidos.']], 'En reposo, el corazón de un adulto late unas 60 a 100 veces por minuto; se acelera con el esfuerzo.'],
    de:['Wie oft schlägt das Herz eines Erwachsenen in Ruhe ungefähr pro Minute?', 'Zwischen 60- und 100-mal', [['Etwa 5-mal', 'Fünf Schläge pro Minute? Dein Herz würde Mittagsschlaf machen. In Ruhe sind es 60 bis 100.'], ['Etwa 1000-mal', 'Tausend? Das ist ein Kolibri, kein Mensch! In Ruhe sind es 60 bis 100 Schläge.']], 'In Ruhe schlägt das Herz eines Erwachsenen etwa 60- bis 100-mal pro Minute; bei Anstrengung schneller.'],
    it:['A riposo, quante volte batte circa il cuore di un adulto al minuto?', 'Tra 60 e 100 volte', [['Circa 5 volte', 'Cinque battiti al minuto? Il tuo cuore farebbe un pisolino. A riposo sono tra 60 e 100.'], ['Circa 1000 volte', 'Mille? Quello è un colibrì, non un umano! A riposo sono tra 60 e 100 battiti.']], 'A riposo il cuore di un adulto batte circa 60-100 volte al minuto; accelera durante lo sforzo.'],
    pt:['Em repouso, quantas vezes bate mais ou menos o coração de um adulto por minuto?', 'Entre 60 e 100 vezes', [['Cerca de 5 vezes', 'Cinco batimentos por minuto? O teu coração estaria a dormir a sesta. Em repouso são entre 60 e 100.'], ['Cerca de 1000 vezes', 'Mil? Isso é um colibri, não um humano! Em repouso são entre 60 e 100 batimentos.']], 'Em repouso, o coração de um adulto bate cerca de 60 a 100 vezes por minuto; acelera com o esforço.']
  });
  P('muscles', 'corps', {
    fr:['Comment les muscles font-ils bouger les os ?', 'Ils se contractent et tirent sur les os', [['Ils poussent les os', 'Un muscle ne sait pas pousser, il ne sait que tirer ! C’est pour ça qu’ils travaillent par paires.'], ['Ils se gonflent d’air', 'Des muscles gonflables ? Tu n’es pas une bouée. Ils se contractent et tirent sur les os.']], 'Un muscle ne peut que tirer en se contractant. Pour plier puis tendre le bras, le biceps et le triceps travaillent à tour de rôle.'],
    en:['How do muscles move the bones?', 'They contract and pull on the bones', [['They push the bones', 'A muscle cannot push, it can only pull! That is why muscles work in pairs.'], ['They fill up with air', 'Inflatable muscles? You are not a rubber ring. They contract and pull on the bones.']], 'A muscle can only pull, by contracting. To bend and straighten your arm, the biceps and triceps take turns.'],
    es:['¿Cómo mueven los músculos los huesos?', 'Se contraen y tiran de los huesos', [['Empujan los huesos', '¡Un músculo no sabe empujar, solo tirar! Por eso trabajan por parejas.'], ['Se hinchan de aire', '¿Músculos hinchables? No eres un flotador. Se contraen y tiran de los huesos.']], 'Un músculo solo puede tirar al contraerse. Para doblar y estirar el brazo, el bíceps y el tríceps se turnan.'],
    de:['Wie bewegen Muskeln die Knochen?', 'Sie ziehen sich zusammen und ziehen an den Knochen', [['Sie schieben die Knochen', 'Ein Muskel kann nicht schieben, nur ziehen! Darum arbeiten Muskeln paarweise.'], ['Sie pumpen sich mit Luft auf', 'Aufblasbare Muskeln? Du bist kein Schwimmring. Sie ziehen sich zusammen und ziehen an den Knochen.']], 'Ein Muskel kann nur ziehen, indem er sich zusammenzieht. Zum Beugen und Strecken des Arms wechseln sich Bizeps und Trizeps ab.'],
    it:['Come fanno i muscoli a muovere le ossa?', 'Si contraggono e tirano le ossa', [['Spingono le ossa', 'Un muscolo non sa spingere, sa solo tirare! Per questo lavorano in coppia.'], ['Si gonfiano d’aria', 'Muscoli gonfiabili? Non sei un salvagente. Si contraggono e tirano le ossa.']], 'Un muscolo può solo tirare, contraendosi. Per piegare e stendere il braccio, bicipite e tricipite si danno il cambio.'],
    pt:['Como é que os músculos mexem os ossos?', 'Contraem-se e puxam os ossos', [['Empurram os ossos', 'Um músculo não sabe empurrar, só puxar! É por isso que trabalham aos pares.'], ['Enchem-se de ar', 'Músculos insufláveis? Não és uma boia. Contraem-se e puxam os ossos.']], 'Um músculo só consegue puxar, contraindo-se. Para dobrar e esticar o braço, o bíceps e o tríceps revezam-se.']
  });
  P('pupille', 'corps', {
    fr:['À quoi sert la pupille, le rond noir au centre de l’œil ?', 'À laisser entrer la lumière', [['À fabriquer les larmes', 'Les larmes viennent de petites glandes près de l’œil, pas de la pupille. Elle, c’est la porte d’entrée de la lumière.'], ['À donner la couleur des yeux', 'La couleur, c’est l’iris, l’anneau autour ! La pupille est un trou qui laisse passer la lumière.']], 'La pupille est une ouverture : elle rétrécit en pleine lumière et s’agrandit dans le noir pour laisser entrer plus de lumière.'],
    en:['What is the pupil, the black circle in the middle of the eye, for?', 'Letting light in', [['Making tears', 'Tears come from small glands near the eye, not the pupil. The pupil is the doorway for light.'], ['Giving the eyes their colour', 'The colour is the iris, the ring around it! The pupil is a hole that lets light through.']], 'The pupil is an opening: it gets smaller in bright light and bigger in the dark to let more light in.'],
    es:['¿Para qué sirve la pupila, el círculo negro en el centro del ojo?', 'Para dejar entrar la luz', [['Para fabricar las lágrimas', 'Las lágrimas vienen de unas glándulas cerca del ojo, no de la pupila. Ella es la puerta de entrada de la luz.'], ['Para dar el color de los ojos', '¡El color es el iris, el anillo de alrededor! La pupila es un agujero que deja pasar la luz.']], 'La pupila es una abertura: se encoge con mucha luz y se agranda en la oscuridad para dejar entrar más luz.'],
    de:['Wofür ist die Pupille, der schwarze Kreis in der Mitte des Auges, da?', 'Um Licht hereinzulassen', [['Um Tränen zu machen', 'Tränen kommen aus kleinen Drüsen am Auge, nicht aus der Pupille. Sie ist die Eingangstür fürs Licht.'], ['Um den Augen ihre Farbe zu geben', 'Die Farbe ist die Iris, der Ring drumherum! Die Pupille ist ein Loch, das Licht durchlässt.']], 'Die Pupille ist eine Öffnung: Bei hellem Licht wird sie kleiner, im Dunkeln größer, um mehr Licht hereinzulassen.'],
    it:['A che cosa serve la pupilla, il cerchio nero al centro dell’occhio?', 'A far entrare la luce', [['A produrre le lacrime', 'Le lacrime vengono da piccole ghiandole vicino all’occhio, non dalla pupilla. Lei è la porta d’ingresso della luce.'], ['A dare il colore agli occhi', 'Il colore è l’iride, l’anello intorno! La pupilla è un foro che lascia passare la luce.']], 'La pupilla è un’apertura: si restringe con tanta luce e si allarga al buio per far entrare più luce.'],
    pt:['Para que serve a pupila, o círculo preto no meio do olho?', 'Para deixar entrar a luz', [['Para fabricar as lágrimas', 'As lágrimas vêm de pequenas glândulas perto do olho, não da pupila. Ela é a porta de entrada da luz.'], ['Para dar a cor aos olhos', 'A cor é a íris, o anel à volta! A pupila é um buraco que deixa passar a luz.']], 'A pupila é uma abertura: encolhe com muita luz e alarga no escuro para deixar entrar mais luz.']
  });
  P('colonne', 'corps', {
    fr:['Comment s’appelle la pile d’os qui soutient le dos ?', 'La colonne vertébrale', [['Le sternum', 'Le sternum est devant, au milieu de la poitrine. Tu as regardé du mauvais côté ! Dans le dos, c’est la colonne vertébrale.'], ['La rotule', 'La rotule est au genou. Tu es descendu un peu trop bas ! C’est la colonne vertébrale.']], 'La colonne vertébrale est faite de vertèbres empilées. Elle soutient le corps et protège la moelle épinière.'],
    en:['What is the stack of bones that holds up your back called?', 'The spine', [['The breastbone', 'The breastbone is at the front, in the middle of your chest. Wrong side! In the back, it is the spine.'], ['The kneecap', 'The kneecap is at the knee. You went a bit too far down! It is the spine.']], 'The spine is made of stacked vertebrae. It holds the body up and protects the spinal cord.'],
    es:['¿Cómo se llama la pila de huesos que sostiene la espalda?', 'La columna vertebral', [['El esternón', 'El esternón está delante, en medio del pecho. ¡Miraste del lado equivocado! En la espalda está la columna vertebral.'], ['La rótula', 'La rótula está en la rodilla. ¡Bajaste demasiado! Es la columna vertebral.']], 'La columna vertebral está hecha de vértebras apiladas. Sostiene el cuerpo y protege la médula espinal.'],
    de:['Wie heißt der Stapel aus Knochen, der den Rücken stützt?', 'Die Wirbelsäule', [['Das Brustbein', 'Das Brustbein ist vorne, mitten auf der Brust. Falsche Seite! Im Rücken ist die Wirbelsäule.'], ['Die Kniescheibe', 'Die Kniescheibe sitzt am Knie. Ein bisschen zu weit unten! Es ist die Wirbelsäule.']], 'Die Wirbelsäule besteht aus gestapelten Wirbeln. Sie stützt den Körper und schützt das Rückenmark.'],
    it:['Come si chiama la pila di ossa che sostiene la schiena?', 'La colonna vertebrale', [['Lo sterno', 'Lo sterno è davanti, in mezzo al petto. Hai guardato dalla parte sbagliata! Nella schiena c’è la colonna vertebrale.'], ['La rotula', 'La rotula è nel ginocchio. Sei sceso un po’ troppo! È la colonna vertebrale.']], 'La colonna vertebrale è fatta di vertebre impilate. Sostiene il corpo e protegge il midollo spinale.'],
    pt:['Como se chama a pilha de ossos que sustenta as costas?', 'A coluna vertebral', [['O esterno', 'O esterno está à frente, no meio do peito. Olhaste para o lado errado! Nas costas está a coluna vertebral.'], ['A rótula', 'A rótula está no joelho. Desceste demasiado! É a coluna vertebral.']], 'A coluna vertebral é feita de vértebras empilhadas. Sustenta o corpo e protege a medula espinal.']
  });
  P('cage', 'corps', {
    fr:['Que protège la cage thoracique (les côtes) ?', 'Le cœur et les poumons', [['Le cerveau', 'Le cerveau a son propre casque : le crâne. Les côtes protègent le cœur et les poumons.'], ['Les genoux', 'Des côtes aux genoux ? Il faudrait des bras de gorille. Elles protègent le cœur et les poumons.']], 'Les côtes forment une cage autour du cœur et des poumons ; elle bouge quand on respire.'],
    en:['What does the ribcage protect?', 'The heart and lungs', [['The brain', 'The brain has its own helmet: the skull. The ribs protect the heart and lungs.'], ['The knees', 'Ribs down to the knees? You would need gorilla arms. They protect the heart and lungs.']], 'The ribs form a cage around the heart and lungs; it moves when we breathe.'],
    es:['¿Qué protege la caja torácica (las costillas)?', 'El corazón y los pulmones', [['El cerebro', 'El cerebro tiene su propio casco: el cráneo. Las costillas protegen el corazón y los pulmones.'], ['Las rodillas', '¿Costillas hasta las rodillas? Harían falta brazos de gorila. Protegen el corazón y los pulmones.']], 'Las costillas forman una caja alrededor del corazón y los pulmones; se mueve al respirar.'],
    de:['Was schützt der Brustkorb (die Rippen)?', 'Das Herz und die Lunge', [['Das Gehirn', 'Das Gehirn hat seinen eigenen Helm: den Schädel. Die Rippen schützen Herz und Lunge.'], ['Die Knie', 'Rippen bis zu den Knien? Dafür müsstest du ein Gorilla sein. Sie schützen Herz und Lunge.']], 'Die Rippen bilden einen Korb um Herz und Lunge; er bewegt sich beim Atmen.'],
    it:['Che cosa protegge la gabbia toracica (le costole)?', 'Il cuore e i polmoni', [['Il cervello', 'Il cervello ha il suo casco: il cranio. Le costole proteggono cuore e polmoni.'], ['Le ginocchia', 'Costole fino alle ginocchia? Servirebbero braccia da gorilla. Proteggono cuore e polmoni.']], 'Le costole formano una gabbia intorno a cuore e polmoni; si muove quando respiriamo.'],
    pt:['O que protege a caixa torácica (as costelas)?', 'O coração e os pulmões', [['O cérebro', 'O cérebro tem o seu próprio capacete: o crânio. As costelas protegem o coração e os pulmões.'], ['Os joelhos', 'Costelas até aos joelhos? Eram precisos braços de gorila. Protegem o coração e os pulmões.']], 'As costelas formam uma caixa à volta do coração e dos pulmões; mexe-se quando respiramos.']
  });
  P('crane', 'corps', {
    fr:['Quel os protège le cerveau ?', 'Le crâne', [['Le fémur', 'Le fémur est dans la cuisse. Réfléchir avec les cuisses, c’est original ! C’est le crâne.'], ['La clavicule', 'La clavicule est à l’épaule, un peu bas pour un casque. Le cerveau est protégé par le crâne.']], 'Le crâne est une boîte d’os soudés qui entoure et protège le cerveau.'],
    en:['Which bone protects the brain?', 'The skull', [['The thighbone', 'The thighbone is in your leg. Thinking with your legs is original! It is the skull.'], ['The collarbone', 'The collarbone is at the shoulder, a bit low for a helmet. The brain is protected by the skull.']], 'The skull is a box of joined bones that surrounds and protects the brain.'],
    es:['¿Qué hueso protege el cerebro?', 'El cráneo', [['El fémur', 'El fémur está en el muslo. ¡Pensar con los muslos es original! Es el cráneo.'], ['La clavícula', 'La clavícula está en el hombro, un poco baja para ser un casco. El cerebro lo protege el cráneo.']], 'El cráneo es una caja de huesos soldados que rodea y protege el cerebro.'],
    de:['Welcher Knochen schützt das Gehirn?', 'Der Schädel', [['Der Oberschenkelknochen', 'Der sitzt im Bein. Mit den Beinen denken ist originell! Es ist der Schädel.'], ['Das Schlüsselbein', 'Das Schlüsselbein ist an der Schulter, etwas tief für einen Helm. Das Gehirn schützt der Schädel.']], 'Der Schädel ist eine Kapsel aus verwachsenen Knochen, die das Gehirn umgibt und schützt.'],
    it:['Quale osso protegge il cervello?', 'Il cranio', [['Il femore', 'Il femore è nella coscia. Pensare con le cosce è originale! È il cranio.'], ['La clavicola', 'La clavicola è alla spalla, un po’ bassa per fare da casco. Il cervello è protetto dal cranio.']], 'Il cranio è una scatola di ossa saldate che circonda e protegge il cervello.'],
    pt:['Que osso protege o cérebro?', 'O crânio', [['O fémur', 'O fémur está na coxa. Pensar com as coxas é original! É o crânio.'], ['A clavícula', 'A clavícula está no ombro, um pouco baixa para capacete. O cérebro é protegido pelo crânio.']], 'O crânio é uma caixa de ossos soldados que rodeia e protege o cérebro.']
  });
  P('plaquettes', 'corps', {
    fr:['Quand on se coupe, quelles cellules aident à refermer la plaie ?', 'Les plaquettes', [['Les globules rouges', 'Les globules rouges sont livreurs d’oxygène, pas réparateurs. Ce sont les plaquettes qui bouchent la fuite.'], ['Les neurones', 'Les neurones envoient des messages, ils ne posent pas de pansement. Ce sont les plaquettes.']], 'Les plaquettes s’agglutinent sur la blessure et forment un bouchon (caillot), puis une croûte.'],
    en:['When you cut yourself, which cells help close the wound?', 'Platelets', [['Red blood cells', 'Red cells deliver oxygen, they do not do repairs. Platelets plug the leak.'], ['Neurons', 'Neurons send messages, they do not put on plasters. It is the platelets.']], 'Platelets clump together on the cut and form a plug (clot), then a scab.'],
    es:['Cuando te cortas, ¿qué células ayudan a cerrar la herida?', 'Las plaquetas', [['Los glóbulos rojos', 'Los glóbulos rojos reparten oxígeno, no hacen reparaciones. Las plaquetas tapan la fuga.'], ['Las neuronas', 'Las neuronas envían mensajes, no ponen tiritas. Son las plaquetas.']], 'Las plaquetas se agrupan en el corte y forman un tapón (coágulo), luego una costra.'],
    de:['Wenn man sich schneidet: Welche Zellen helfen, die Wunde zu schließen?', 'Die Blutplättchen', [['Die roten Blutkörperchen', 'Rote Blutkörperchen liefern Sauerstoff, sie reparieren nichts. Die Blutplättchen stopfen das Leck.'], ['Die Nervenzellen', 'Nervenzellen schicken Nachrichten, sie kleben keine Pflaster. Es sind die Blutplättchen.']], 'Blutplättchen verklumpen an der Wunde und bilden einen Pfropfen (Gerinnsel), dann eine Kruste.'],
    it:['Quando ti tagli, quali cellule aiutano a chiudere la ferita?', 'Le piastrine', [['I globuli rossi', 'I globuli rossi consegnano ossigeno, non fanno riparazioni. Sono le piastrine a tappare la falla.'], ['I neuroni', 'I neuroni mandano messaggi, non mettono cerotti. Sono le piastrine.']], 'Le piastrine si ammassano sul taglio e formano un tappo (coagulo), poi una crosticina.'],
    pt:['Quando te cortas, que células ajudam a fechar a ferida?', 'As plaquetas', [['Os glóbulos vermelhos', 'Os glóbulos vermelhos entregam oxigénio, não fazem reparações. São as plaquetas que tapam a fuga.'], ['Os neurónios', 'Os neurónios enviam mensagens, não põem pensos. São as plaquetas.']], 'As plaquetas juntam-se no corte e formam um tampão (coágulo), depois uma crosta.']
  });
  P('estomac', 'corps', {
    fr:['Que contient l’estomac pour digérer les aliments ?', 'Un liquide très acide', [['De l’eau pure', 'De l’eau pure ? Ton estomac n’est pas une carafe. Il fabrique un suc très acide qui découpe les aliments.'], ['De l’air', 'De l’air ? On n’est pas dans un ballon. L’estomac contient un liquide très acide.']], 'Le suc gastrique, très acide, aide à découper les aliments et tue beaucoup de microbes avalés.'],
    en:['What does the stomach contain to digest food?', 'A very acidic liquid', [['Pure water', 'Pure water? Your stomach is not a jug. It makes a very acidic juice that breaks food down.'], ['Air', 'Air? It is not a balloon. The stomach contains a very acidic liquid.']], 'Gastric juice is very acidic: it helps break food down and kills many swallowed germs.'],
    es:['¿Qué contiene el estómago para digerir los alimentos?', 'Un líquido muy ácido', [['Agua pura', '¿Agua pura? Tu estómago no es una jarra. Fabrica un jugo muy ácido que deshace los alimentos.'], ['Aire', '¿Aire? No es un globo. El estómago contiene un líquido muy ácido.']], 'El jugo gástrico, muy ácido, ayuda a deshacer los alimentos y elimina muchos microbios tragados.'],
    de:['Was enthält der Magen, um das Essen zu verdauen?', 'Eine sehr saure Flüssigkeit', [['Reines Wasser', 'Reines Wasser? Dein Magen ist keine Karaffe. Er macht einen sehr sauren Saft, der das Essen zerlegt.'], ['Luft', 'Luft? Das ist kein Luftballon. Der Magen enthält eine sehr saure Flüssigkeit.']], 'Der Magensaft ist sehr sauer: Er hilft, Nahrung zu zerlegen, und macht viele verschluckte Keime unschädlich.'],
    it:['Che cosa contiene lo stomaco per digerire il cibo?', 'Un liquido molto acido', [['Acqua pura', 'Acqua pura? Il tuo stomaco non è una caraffa. Produce un succo molto acido che scompone il cibo.'], ['Aria', 'Aria? Non è un palloncino. Lo stomaco contiene un liquido molto acido.']], 'Il succo gastrico, molto acido, aiuta a scomporre il cibo ed elimina molti microbi ingoiati.'],
    pt:['O que contém o estômago para digerir os alimentos?', 'Um líquido muito ácido', [['Água pura', 'Água pura? O teu estômago não é um jarro. Fabrica um suco muito ácido que desfaz os alimentos.'], ['Ar', 'Ar? Não é um balão. O estômago contém um líquido muito ácido.']], 'O suco gástrico, muito ácido, ajuda a desfazer os alimentos e elimina muitos micróbios engolidos.']
  });
  P('neurones', 'corps', {
    fr:['Comment s’appellent les cellules du cerveau qui transmettent les messages ?', 'Les neurones', [['Les globules', 'Les globules voyagent dans les vaisseaux, pas dans les idées. Le cerveau, lui, fonctionne avec des neurones.'], ['Les vertèbres', 'Les vertèbres sont des os du dos. Pas très bavardes ! Les messagers du cerveau, ce sont les neurones.']], 'Le cerveau compte environ 86 milliards de neurones, reliés entre eux par des signaux électriques et chimiques.'],
    en:['What are the brain cells that pass on messages called?', 'Neurons', [['Corpuscles', 'Corpuscles travel through your veins, not your thoughts. The brain works with neurons.'], ['Vertebrae', 'Vertebrae are back bones. Not very chatty! The brain’s messengers are neurons.']], 'The brain has about 86 billion neurons, linked by electrical and chemical signals.'],
    es:['¿Cómo se llaman las células del cerebro que transmiten los mensajes?', 'Las neuronas', [['Los glóbulos', 'Los glóbulos viajan por las venas, no por las ideas. El cerebro funciona con neuronas.'], ['Las vértebras', 'Las vértebras son huesos de la espalda. ¡Poco habladoras! Las mensajeras del cerebro son las neuronas.']], 'El cerebro tiene unos 86 000 millones de neuronas, conectadas por señales eléctricas y químicas.'],
    de:['Wie heißen die Gehirnzellen, die Nachrichten weitergeben?', 'Nervenzellen (Neuronen)', [['Blutkörperchen', 'Blutkörperchen reisen durch die Adern, nicht durch Gedanken. Das Gehirn arbeitet mit Neuronen.'], ['Wirbel', 'Wirbel sind Rückenknochen. Nicht sehr gesprächig! Die Boten des Gehirns sind Neuronen.']], 'Das Gehirn hat etwa 86 Milliarden Neuronen, verbunden durch elektrische und chemische Signale.'],
    it:['Come si chiamano le cellule del cervello che trasmettono i messaggi?', 'I neuroni', [['I globuli', 'I globuli viaggiano nelle vene, non nei pensieri. Il cervello funziona con i neuroni.'], ['Le vertebre', 'Le vertebre sono ossa della schiena. Poco chiacchierone! I messaggeri del cervello sono i neuroni.']], 'Il cervello ha circa 86 miliardi di neuroni, collegati da segnali elettrici e chimici.'],
    pt:['Como se chamam as células do cérebro que transmitem as mensagens?', 'Os neurónios', [['Os glóbulos', 'Os glóbulos viajam nas veias, não nos pensamentos. O cérebro funciona com neurónios.'], ['As vértebras', 'As vértebras são ossos das costas. Pouco faladoras! Os mensageiros do cérebro são os neurónios.']], 'O cérebro tem cerca de 86 mil milhões de neurónios, ligados por sinais elétricos e químicos.']
  });
  P('sommeil', 'corps', {
    fr:['Pourquoi le sommeil est-il important ?', 'Le corps récupère et le cerveau range ce qu’on a appris', [['Il ne sert à rien', 'À rien ? Essaie une nuit blanche avant un contrôle, tu verras ! Le cerveau range les leçons pendant la nuit.'], ['Il fait pousser les cheveux', 'Les cheveux poussent jour et nuit, sommeil ou pas. Dormir, c’est récupérer et ranger ce qu’on a appris.']], 'Pendant le sommeil, le corps se répare, grandit (hormone de croissance) et le cerveau consolide la mémoire.'],
    en:['Why is sleep important?', 'The body recovers and the brain stores what we learnt', [['It is useless', 'Useless? Try staying up all night before a test! The brain files lessons away at night.'], ['It makes your hair grow', 'Hair grows day and night, asleep or not. Sleep is for recovering and storing what you learnt.']], 'During sleep, the body repairs itself and grows (growth hormone), and the brain strengthens memories.'],
    es:['¿Por qué es importante dormir?', 'El cuerpo se recupera y el cerebro ordena lo aprendido', [['No sirve para nada', '¿Para nada? ¡Prueba a pasar la noche en vela antes de un examen! El cerebro ordena las lecciones por la noche.'], ['Hace crecer el pelo', 'El pelo crece de día y de noche, duermas o no. Dormir sirve para recuperarse y ordenar lo aprendido.']], 'Mientras dormimos, el cuerpo se repara y crece (hormona del crecimiento), y el cerebro afianza la memoria.'],
    de:['Warum ist Schlaf wichtig?', 'Der Körper erholt sich und das Gehirn sortiert das Gelernte', [['Er bringt gar nichts', 'Gar nichts? Bleib mal vor einer Klassenarbeit die ganze Nacht wach! Nachts sortiert das Gehirn das Gelernte.'], ['Er lässt die Haare wachsen', 'Haare wachsen Tag und Nacht, ob du schläfst oder nicht. Schlaf ist zum Erholen und zum Speichern des Gelernten.']], 'Im Schlaf repariert sich der Körper, wächst (Wachstumshormon), und das Gehirn festigt Erinnerungen.'],
    it:['Perché il sonno è importante?', 'Il corpo si riposa e il cervello mette in ordine ciò che ha imparato', [['Non serve a niente', 'A niente? Prova a stare sveglio tutta la notte prima di una verifica! Il cervello sistema le lezioni di notte.'], ['Fa crescere i capelli', 'I capelli crescono giorno e notte, sonno o no. Dormire serve a recuperare e a mettere in ordine ciò che si è imparato.']], 'Durante il sonno il corpo si ripara e cresce (ormone della crescita), e il cervello consolida la memoria.'],
    pt:['Porque é que o sono é importante?', 'O corpo recupera e o cérebro arruma o que aprendemos', [['Não serve para nada', 'Para nada? Experimenta passar a noite em claro antes de um teste! O cérebro arruma as lições durante a noite.'], ['Faz crescer o cabelo', 'O cabelo cresce de dia e de noite, com ou sem sono. Dormir serve para recuperar e arrumar o que se aprendeu.']], 'Durante o sono, o corpo repara-se e cresce (hormona do crescimento), e o cérebro consolida a memória.']
  });

  // ── 🩺 Médecine et microbes ──
  P('virus-taille', 'medecine', {
    fr:['Un virus est…', 'Beaucoup plus petit qu’une bactérie', [['Plus grand qu’une fourmi', 'Plus grand qu’une fourmi ? On les écraserait avec une chaussure. Il faut un microscope très puissant pour les voir.'], ['Visible à l’œil nu', 'À l’œil nu ? Même avec tes meilleures lunettes, non. Un virus est bien plus petit qu’une bactérie.']], 'Les virus sont si petits qu’il faut un microscope électronique pour les voir ; ils ont besoin de nos cellules pour se multiplier.'],
    en:['A virus is…', 'Much smaller than a bacterium', [['Bigger than an ant', 'Bigger than an ant? We could just step on them. You need a very powerful microscope to see them.'], ['Visible to the naked eye', 'With the naked eye? Not even with your best glasses. A virus is much smaller than a bacterium.']], 'Viruses are so small that you need an electron microscope to see them; they need our cells to multiply.'],
    es:['Un virus es…', 'Mucho más pequeño que una bacteria', [['Más grande que una hormiga', '¿Más grande que una hormiga? Los pisaríamos con el zapato. Hace falta un microscopio muy potente para verlos.'], ['Visible a simple vista', '¿A simple vista? Ni con tus mejores gafas. Un virus es mucho más pequeño que una bacteria.']], 'Los virus son tan pequeños que hace falta un microscopio electrónico para verlos; necesitan nuestras células para multiplicarse.'],
    de:['Ein Virus ist…', 'Viel kleiner als ein Bakterium', [['Größer als eine Ameise', 'Größer als eine Ameise? Dann könnte man drauftreten. Man braucht ein sehr starkes Mikroskop, um Viren zu sehen.'], ['Mit bloßem Auge sichtbar', 'Mit bloßem Auge? Nicht mal mit deiner besten Brille. Ein Virus ist viel kleiner als ein Bakterium.']], 'Viren sind so klein, dass man ein Elektronenmikroskop braucht; sie brauchen unsere Zellen, um sich zu vermehren.'],
    it:['Un virus è…', 'Molto più piccolo di un batterio', [['Più grande di una formica', 'Più grande di una formica? Li schiacceremmo con la scarpa. Serve un microscopio potentissimo per vederli.'], ['Visibile a occhio nudo', 'A occhio nudo? Nemmeno con i tuoi occhiali migliori. Un virus è molto più piccolo di un batterio.']], 'I virus sono così piccoli che serve un microscopio elettronico per vederli; hanno bisogno delle nostre cellule per moltiplicarsi.'],
    pt:['Um vírus é…', 'Muito mais pequeno do que uma bactéria', [['Maior do que uma formiga', 'Maior do que uma formiga? Pisávamo-los com o sapato. É preciso um microscópio muito potente para os ver.'], ['Visível a olho nu', 'A olho nu? Nem com os teus melhores óculos. Um vírus é muito mais pequeno do que uma bactéria.']], 'Os vírus são tão pequenos que é preciso um microscópio eletrónico para os ver; precisam das nossas células para se multiplicarem.']
  });
  P('fievre', 'medecine', {
    fr:['La fièvre, c’est…', 'Une hausse de la température du corps pour lutter contre une infection', [['Un microbe', 'La fièvre n’est pas un microbe, c’est la RÉPONSE du corps à un microbe. Il monte le chauffage pour le gêner.'], ['Une maladie des cheveux', 'Des cheveux fiévreux ? Ils n’ont pas de thermomètre. La fièvre, c’est le corps qui chauffe.']], 'On parle de fièvre au-dessus d’environ 38 °C. C’est souvent un signe que le corps se défend contre une infection.'],
    en:['A fever is…', 'A rise in body temperature to fight an infection', [['A germ', 'A fever is not a germ, it is the body’s RESPONSE to a germ. It turns up the heating to slow it down.'], ['A hair illness', 'Feverish hair? Hair has no thermometer. A fever is the body heating up.']], 'A fever usually means above about 38 °C. It is often a sign that the body is fighting an infection.'],
    es:['La fiebre es…', 'Una subida de la temperatura del cuerpo para luchar contra una infección', [['Un microbio', 'La fiebre no es un microbio, es la RESPUESTA del cuerpo a un microbio. Sube la calefacción para frenarlo.'], ['Una enfermedad del pelo', '¿Pelo con fiebre? El pelo no tiene termómetro. La fiebre es el cuerpo que se calienta.']], 'Se habla de fiebre por encima de unos 38 °C. Suele ser señal de que el cuerpo se defiende de una infección.'],
    de:['Fieber ist…', 'Ein Anstieg der Körpertemperatur, um eine Infektion zu bekämpfen', [['Ein Keim', 'Fieber ist kein Keim, sondern die ANTWORT des Körpers auf einen Keim. Er dreht die Heizung hoch, um ihn auszubremsen.'], ['Eine Haarkrankheit', 'Fiebrige Haare? Haare haben kein Thermometer. Fieber heißt: Der Körper heizt.']], 'Von Fieber spricht man ab etwa 38 °C. Oft ist es ein Zeichen, dass sich der Körper gegen eine Infektion wehrt.'],
    it:['La febbre è…', 'Un aumento della temperatura del corpo per combattere un’infezione', [['Un microbo', 'La febbre non è un microbo, è la RISPOSTA del corpo a un microbo. Alza il riscaldamento per rallentarlo.'], ['Una malattia dei capelli', 'Capelli con la febbre? I capelli non hanno il termometro. La febbre è il corpo che si scalda.']], 'Si parla di febbre sopra i 38 °C circa. Spesso è il segno che il corpo si difende da un’infezione.'],
    pt:['A febre é…', 'Uma subida da temperatura do corpo para combater uma infeção', [['Um micróbio', 'A febre não é um micróbio, é a RESPOSTA do corpo a um micróbio. Sobe o aquecimento para o travar.'], ['Uma doença do cabelo', 'Cabelo com febre? O cabelo não tem termómetro. A febre é o corpo a aquecer.']], 'Fala-se de febre acima de cerca de 38 °C. Muitas vezes é sinal de que o corpo se defende de uma infeção.']
  });
  P('jenner', 'medecine', {
    fr:['Qui a mis au point le premier vaccin, contre la variole, en 1796 ?', 'Edward Jenner', [['Louis Pasteur', 'Pasteur, c’est le vaccin contre la rage, en 1885 : presque un siècle plus tard. Le pionnier, c’est Edward Jenner.'], ['Marie Curie', 'Marie Curie, c’est la radioactivité, pas les vaccins. Le premier vaccin, c’est Edward Jenner.']], 'Le médecin anglais Edward Jenner a utilisé la variole de la vache (« vaccine ») pour protéger contre la variole : d’où le mot « vaccin ».'],
    en:['Who developed the first vaccine, against smallpox, in 1796?', 'Edward Jenner', [['Louis Pasteur', 'Pasteur made the rabies vaccine in 1885, almost a century later. The pioneer was Edward Jenner.'], ['Marie Curie', 'Marie Curie worked on radioactivity, not vaccines. The first vaccine was Edward Jenner’s.']], 'The English doctor Edward Jenner used cowpox (Latin “vacca” = cow) to protect against smallpox: that is where “vaccine” comes from.'],
    es:['¿Quién creó la primera vacuna, contra la viruela, en 1796?', 'Edward Jenner', [['Louis Pasteur', 'Pasteur hizo la vacuna contra la rabia en 1885, casi un siglo después. El pionero fue Edward Jenner.'], ['Marie Curie', 'Marie Curie trabajó en la radiactividad, no en vacunas. La primera vacuna fue la de Edward Jenner.']], 'El médico inglés Edward Jenner usó la viruela de las vacas para proteger contra la viruela: de ahí viene la palabra «vacuna».'],
    de:['Wer entwickelte 1796 den ersten Impfstoff, gegen die Pocken?', 'Edward Jenner', [['Louis Pasteur', 'Pasteur entwickelte 1885 den Impfstoff gegen Tollwut, fast ein Jahrhundert später. Der Pionier war Edward Jenner.'], ['Marie Curie', 'Marie Curie erforschte die Radioaktivität, nicht Impfstoffe. Der erste Impfstoff stammt von Edward Jenner.']], 'Der englische Arzt Edward Jenner nutzte Kuhpocken (lateinisch „vacca“ = Kuh), um vor Pocken zu schützen: daher das Wort „Vakzin“.'],
    it:['Chi ha messo a punto il primo vaccino, contro il vaiolo, nel 1796?', 'Edward Jenner', [['Louis Pasteur', 'Pasteur ha fatto il vaccino contro la rabbia nel 1885, quasi un secolo dopo. Il pioniere è Edward Jenner.'], ['Marie Curie', 'Marie Curie ha studiato la radioattività, non i vaccini. Il primo vaccino è di Edward Jenner.']], 'Il medico inglese Edward Jenner usò il vaiolo delle mucche per proteggere dal vaiolo: da qui la parola «vaccino» (dal latino «vacca»).'],
    pt:['Quem criou a primeira vacina, contra a varíola, em 1796?', 'Edward Jenner', [['Louis Pasteur', 'Pasteur fez a vacina contra a raiva em 1885, quase um século depois. O pioneiro foi Edward Jenner.'], ['Marie Curie', 'Marie Curie estudou a radioatividade, não as vacinas. A primeira vacina foi a de Edward Jenner.']], 'O médico inglês Edward Jenner usou a varíola das vacas para proteger contra a varíola: daí a palavra «vacina».']
  });
  P('curie', 'medecine', {
    fr:['Marie Curie a reçu deux prix Nobel pour ses travaux sur…', 'La radioactivité', [['Les vaccins', 'Les vaccins, c’est Jenner et Pasteur. Marie Curie, elle, a étudié la radioactivité.'], ['Les vitamines', 'Les vitamines ? Pas son rayon. Son rayon, c’était justement les rayonnements : la radioactivité.']], 'Marie Curie a reçu le prix Nobel de physique (1903) puis de chimie (1911) ; elle a découvert le polonium et le radium.'],
    en:['Marie Curie won two Nobel Prizes for her work on…', 'Radioactivity', [['Vaccines', 'Vaccines were Jenner and Pasteur. Marie Curie studied radioactivity.'], ['Vitamins', 'Vitamins? Not her field. Her field was radiation: radioactivity.']], 'Marie Curie won the Nobel Prize in Physics (1903) and in Chemistry (1911); she discovered polonium and radium.'],
    es:['Marie Curie recibió dos premios Nobel por sus trabajos sobre…', 'La radiactividad', [['Las vacunas', 'Las vacunas son cosa de Jenner y Pasteur. Marie Curie estudió la radiactividad.'], ['Las vitaminas', '¿Las vitaminas? No era lo suyo. Lo suyo eran las radiaciones: la radiactividad.']], 'Marie Curie recibió el Nobel de Física (1903) y el de Química (1911); descubrió el polonio y el radio.'],
    de:['Marie Curie erhielt zwei Nobelpreise für ihre Arbeiten über…', 'Die Radioaktivität', [['Impfstoffe', 'Impfstoffe waren Jenner und Pasteur. Marie Curie erforschte die Radioaktivität.'], ['Vitamine', 'Vitamine? Nicht ihr Gebiet. Ihr Gebiet war die Strahlung: Radioaktivität.']], 'Marie Curie erhielt den Nobelpreis für Physik (1903) und für Chemie (1911); sie entdeckte Polonium und Radium.'],
    it:['Marie Curie ha ricevuto due premi Nobel per i suoi studi su…', 'La radioattività', [['I vaccini', 'I vaccini sono Jenner e Pasteur. Marie Curie ha studiato la radioattività.'], ['Le vitamine', 'Le vitamine? Non era il suo campo. Il suo campo erano le radiazioni: la radioattività.']], 'Marie Curie ha ricevuto il Nobel per la fisica (1903) e per la chimica (1911); ha scoperto il polonio e il radio.'],
    pt:['Marie Curie recebeu dois prémios Nobel pelos seus trabalhos sobre…', 'A radioatividade', [['As vacinas', 'As vacinas são Jenner e Pasteur. Marie Curie estudou a radioatividade.'], ['As vitaminas', 'As vitaminas? Não era a área dela. A área dela eram as radiações: a radioatividade.']], 'Marie Curie recebeu o Nobel da Física (1903) e o da Química (1911); descobriu o polónio e o rádio.']
  });
  P('microscope', 'medecine', {
    fr:['Quel instrument permet de voir les microbes ?', 'Le microscope', [['Le télescope', 'Le télescope regarde les étoiles, très loin. Pour le tout petit tout près, c’est le microscope.'], ['Le stéthoscope', 'Le stéthoscope écoute, il ne voit rien ! Pour voir les microbes, il faut un microscope.']], 'Le microscope grossit des centaines de fois : au XVIIe siècle, Antoni van Leeuwenhoek y a observé les premières bactéries.'],
    en:['Which instrument lets you see germs?', 'A microscope', [['A telescope', 'A telescope looks at stars, far away. For tiny things up close, it is a microscope.'], ['A stethoscope', 'A stethoscope listens, it does not see anything! To see germs you need a microscope.']], 'A microscope magnifies hundreds of times: in the 17th century, Antoni van Leeuwenhoek saw the first bacteria with one.'],
    es:['¿Qué instrumento permite ver los microbios?', 'El microscopio', [['El telescopio', 'El telescopio mira las estrellas, muy lejos. Para lo diminuto y cercano, el microscopio.'], ['El estetoscopio', '¡El estetoscopio escucha, no ve nada! Para ver microbios hace falta un microscopio.']], 'El microscopio aumenta cientos de veces: en el siglo XVII, Antoni van Leeuwenhoek observó con él las primeras bacterias.'],
    de:['Mit welchem Instrument kann man Keime sehen?', 'Mit dem Mikroskop', [['Mit dem Teleskop', 'Das Teleskop schaut auf Sterne, ganz weit weg. Für winzig Kleines aus der Nähe nimmt man ein Mikroskop.'], ['Mit dem Stethoskop', 'Das Stethoskop hört, es sieht nichts! Um Keime zu sehen, braucht man ein Mikroskop.']], 'Ein Mikroskop vergrößert hunderte Male: Im 17. Jahrhundert sah Antoni van Leeuwenhoek damit die ersten Bakterien.'],
    it:['Quale strumento permette di vedere i microbi?', 'Il microscopio', [['Il telescopio', 'Il telescopio guarda le stelle, lontanissime. Per il piccolissimo e vicino serve il microscopio.'], ['Lo stetoscopio', 'Lo stetoscopio ascolta, non vede niente! Per vedere i microbi serve un microscopio.']], 'Il microscopio ingrandisce centinaia di volte: nel Seicento Antoni van Leeuwenhoek vi osservò i primi batteri.'],
    pt:['Que instrumento permite ver os micróbios?', 'O microscópio', [['O telescópio', 'O telescópio olha para as estrelas, muito longe. Para o minúsculo e próximo, é o microscópio.'], ['O estetoscópio', 'O estetoscópio ouve, não vê nada! Para ver micróbios é preciso um microscópio.']], 'O microscópio aumenta centenas de vezes: no século XVII, Antoni van Leeuwenhoek observou com ele as primeiras bactérias.']
  });
  P('groupe-sanguin', 'medecine', {
    fr:['Pourquoi vérifie-t-on le groupe sanguin avant une transfusion ?', 'Tous les sangs ne sont pas compatibles entre eux', [['Pour choisir la couleur', 'La couleur ? Tous sont rouges ! Ce qui compte, c’est la compatibilité entre donneur et receveur.'], ['Pour connaître l’âge du donneur', 'L’âge ne se lit pas dans le groupe sanguin. On le vérifie pour que les sangs soient compatibles.']], 'Il existe quatre grands groupes (A, B, AB, O), plus le facteur Rhésus. Un mauvais mélange peut être dangereux.'],
    en:['Why do doctors check the blood group before a transfusion?', 'Not all blood types are compatible with each other', [['To choose the colour', 'The colour? It is all red! What matters is whether donor and receiver are compatible.'], ['To find out the donor’s age', 'Your group says nothing about how old you are. It is checked so donor and receiver match.']], 'There are four main groups (A, B, AB, O), plus the Rhesus factor. A wrong mix can be dangerous.'],
    es:['¿Por qué se comprueba el grupo sanguíneo antes de una transfusión?', 'No todas las sangres son compatibles entre sí', [['Para elegir el color', '¿El color? ¡Todas son rojas! Lo que importa es que donante y receptor sean compatibles.'], ['Para saber la edad del donante', 'La edad no se lee en el grupo sanguíneo. Se comprueba para que sean compatibles.']], 'Hay cuatro grandes grupos (A, B, AB, O), más el factor Rh. Una mala mezcla puede ser peligrosa.'],
    de:['Warum prüft man vor einer Bluttransfusion die Blutgruppe?', 'Nicht alle Blutgruppen passen zueinander', [['Um die Farbe auszusuchen', 'Die Farbe? Alles ist rot! Wichtig ist, ob Spender und Empfänger zusammenpassen.'], ['Um das Alter des Spenders zu erfahren', 'Das Alter steht nicht in der Blutgruppe. Man prüft sie, damit alles zusammenpasst.']], 'Es gibt vier Hauptgruppen (A, B, AB, 0), dazu den Rhesusfaktor. Eine falsche Mischung kann gefährlich sein.'],
    it:['Perché si controlla il gruppo sanguigno prima di una trasfusione?', 'Non tutti i gruppi sono compatibili tra loro', [['Per scegliere il colore', 'Il colore? Sono tutti rossi! Conta che donatore e ricevente siano compatibili.'], ['Per sapere l’età del donatore', 'L’età non si legge nel gruppo sanguigno. Si controlla perché siano compatibili.']], 'Esistono quattro gruppi principali (A, B, AB, 0), più il fattore Rh. Un abbinamento sbagliato può essere pericoloso.'],
    pt:['Porque se verifica o grupo sanguíneo antes de uma transfusão?', 'Nem todos os grupos são compatíveis entre si', [['Para escolher a cor', 'A cor? São todos vermelhos! O que conta é o dador e o recetor serem compatíveis.'], ['Para saber a idade do dador', 'A idade não se lê no grupo sanguíneo. Verifica-se para que sejam compatíveis.']], 'Há quatro grandes grupos (A, B, AB, O), mais o fator Rh. Uma mistura errada pode ser perigosa.']
  });
  P('scorbut', 'medecine', {
    fr:['Quelle maladie des marins était due à un manque de vitamine C ?', 'Le scorbut', [['Le rhume', 'Le rhume vient d’un virus, pas d’un manque de vitamine. La maladie des marins, c’est le scorbut.'], ['Le mal de mer', 'Le mal de mer vient du roulis du bateau, pas d’une vitamine. C’est le scorbut.']], 'Sans fruits ni légumes frais pendant les longs voyages, les marins attrapaient le scorbut. Les agrumes le préviennent.'],
    en:['Which sailors’ illness was caused by a lack of vitamin C?', 'Scurvy', [['The common cold', 'A cold comes from a virus, not a lack of vitamins. The sailors’ illness was scurvy.'], ['Seasickness', 'Seasickness comes from the rolling of the boat, not a vitamin. It is scurvy.']], 'With no fresh fruit or vegetables on long voyages, sailors got scurvy. Citrus fruit prevents it.'],
    es:['¿Qué enfermedad de los marineros se debía a la falta de vitamina C?', 'El escorbuto', [['El resfriado', 'El resfriado viene de un virus, no de una falta de vitamina. La enfermedad de los marineros es el escorbuto.'], ['El mareo', 'El mareo viene del vaivén del barco, no de una vitamina. Es el escorbuto.']], 'Sin fruta ni verdura fresca en los viajes largos, los marineros sufrían escorbuto. Los cítricos lo previenen.'],
    de:['Welche Seefahrerkrankheit kam von zu wenig Vitamin C?', 'Skorbut', [['Schnupfen', 'Schnupfen kommt von einem Virus, nicht von Vitaminmangel. Die Seefahrerkrankheit ist Skorbut.'], ['Seekrankheit', 'Seekrankheit kommt vom Schaukeln des Schiffs, nicht von einem Vitamin. Es ist Skorbut.']], 'Ohne frisches Obst und Gemüse auf langen Reisen bekamen Seeleute Skorbut. Zitrusfrüchte beugen vor.'],
    it:['Quale malattia dei marinai era dovuta alla mancanza di vitamina C?', 'Lo scorbuto', [['Il raffreddore', 'Il raffreddore viene da un virus, non da una carenza di vitamine. La malattia dei marinai è lo scorbuto.'], ['Il mal di mare', 'Il mal di mare viene dal rollio della nave, non da una vitamina. È lo scorbuto.']], 'Senza frutta e verdura fresca nei lunghi viaggi, i marinai si ammalavano di scorbuto. Gli agrumi lo prevengono.'],
    pt:['Que doença dos marinheiros se devia à falta de vitamina C?', 'O escorbuto', [['A constipação', 'A constipação vem de um vírus, não de falta de vitamina. A doença dos marinheiros é o escorbuto.'], ['O enjoo', 'O enjoo vem do balanço do barco, não de uma vitamina. É o escorbuto.']], 'Sem fruta nem legumes frescos nas viagens longas, os marinheiros apanhavam escorbuto. Os citrinos previnem-no.']
  });
  P('thermometre', 'medecine', {
    fr:['À quoi sert un thermomètre médical ?', 'À mesurer la température du corps', [['À mesurer la taille', 'Pour la taille, c’est la toise ou le mètre. Le thermomètre mesure la température.'], ['À écouter le cœur', 'Écouter le cœur, c’est le stéthoscope. Le thermomètre, lui, prend la température.']], 'Le thermomètre médical sert à repérer la fièvre ; la température normale du corps est d’environ 37 °C.'],
    en:['What is a medical thermometer for?', 'Measuring body temperature', [['Measuring height', 'For height you use a measuring stick. A thermometer measures temperature.'], ['Listening to the heart', 'Listening to the heart is the stethoscope’s job. The thermometer takes your temperature.']], 'A medical thermometer helps spot a fever; normal body temperature is about 37 °C.'],
    es:['¿Para qué sirve un termómetro médico?', 'Para medir la temperatura del cuerpo', [['Para medir la estatura', 'Para la estatura se usa el tallímetro. El termómetro mide la temperatura.'], ['Para escuchar el corazón', 'Escuchar el corazón es cosa del estetoscopio. El termómetro toma la temperatura.']], 'El termómetro médico sirve para detectar la fiebre; la temperatura normal del cuerpo es de unos 37 °C.'],
    de:['Wofür ist ein Fieberthermometer da?', 'Um die Körpertemperatur zu messen', [['Um die Körpergröße zu messen', 'Für die Größe nimmt man einen Messstab. Das Thermometer misst die Temperatur.'], ['Um das Herz abzuhören', 'Das Herz hört man mit dem Stethoskop ab. Das Thermometer misst die Temperatur.']], 'Mit dem Fieberthermometer erkennt man Fieber; normal sind etwa 37 °C.'],
    it:['A che cosa serve un termometro medico?', 'A misurare la temperatura del corpo', [['A misurare l’altezza', 'Per l’altezza si usa il metro. Il termometro misura la temperatura.'], ['Ad ascoltare il cuore', 'Ascoltare il cuore è il lavoro dello stetoscopio. Il termometro misura la temperatura.']], 'Il termometro medico serve a scoprire la febbre; la temperatura normale del corpo è circa 37 °C.'],
    pt:['Para que serve um termómetro médico?', 'Para medir a temperatura do corpo', [['Para medir a altura', 'Para a altura usa-se uma fita métrica. O termómetro mede a temperatura.'], ['Para ouvir o coração', 'Ouvir o coração é trabalho do estetoscópio. O termómetro mede a temperatura.']], 'O termómetro médico serve para detetar a febre; a temperatura normal do corpo é de cerca de 37 °C.']
  });
  P('caries', 'medecine', {
    fr:['Qu’est-ce qui provoque les caries ?', 'Des bactéries qui se nourrissent du sucre et abîment l’émail', [['Le froid', 'Le froid peut rendre une dent sensible, mais il ne la troue pas. Les coupables : des bactéries gourmandes de sucre.'], ['Se brosser trop souvent les dents', 'Trop se brosser ? C’est justement ce qui chasse les bactéries ! Les caries viennent de bactéries qui adorent le sucre.']], 'Les bactéries de la bouche transforment le sucre en acide, qui creuse l’émail. Se brosser les dents et limiter le sucre les protège.'],
    en:['What causes tooth decay?', 'Bacteria that feed on sugar and damage the enamel', [['The cold', 'Cold can make a tooth sensitive, but it does not make holes. The culprits: sugar-loving bacteria.'], ['Brushing your teeth too often', 'Brushing too much? That is exactly what gets rid of the bacteria! Decay comes from bacteria that love sugar.']], 'Mouth bacteria turn sugar into acid, which wears away enamel. Brushing and eating less sugar protect your teeth.'],
    es:['¿Qué provoca las caries?', 'Bacterias que se alimentan de azúcar y dañan el esmalte', [['El frío', 'El frío puede hacer que un diente esté sensible, pero no lo agujerea. Las culpables: bacterias golosas de azúcar.'], ['Cepillarse demasiado los dientes', '¿Cepillarse demasiado? ¡Justo eso es lo que echa a las bacterias! Las caries vienen de bacterias que adoran el azúcar.']], 'Las bacterias de la boca convierten el azúcar en ácido, que desgasta el esmalte. Cepillarse y tomar menos azúcar protege los dientes.'],
    de:['Wodurch entsteht Karies?', 'Durch Bakterien, die sich von Zucker ernähren und den Zahnschmelz angreifen', [['Durch Kälte', 'Kälte kann einen Zahn empfindlich machen, aber sie macht keine Löcher. Die Übeltäter: zuckerhungrige Bakterien.'], ['Durch zu häufiges Zähneputzen', 'Zu viel putzen? Genau das vertreibt die Bakterien! Karies kommt von Bakterien, die Zucker lieben.']], 'Bakterien im Mund machen aus Zucker Säure, die den Zahnschmelz angreift. Zähneputzen und weniger Zucker schützen die Zähne.'],
    it:['Che cosa provoca le carie?', 'Batteri che si nutrono di zucchero e rovinano lo smalto', [['Il freddo', 'Il freddo può rendere un dente sensibile, ma non lo buca. I colpevoli: batteri golosi di zucchero.'], ['Lavarsi troppo spesso i denti', 'Lavarsi troppo? È proprio quello che caccia i batteri! Le carie vengono da batteri che adorano lo zucchero.']], 'I batteri della bocca trasformano lo zucchero in acido, che consuma lo smalto. Lavarsi i denti e limitare lo zucchero li protegge.'],
    pt:['O que provoca as cáries?', 'Bactérias que se alimentam de açúcar e estragam o esmalte', [['O frio', 'O frio pode deixar um dente sensível, mas não o fura. As culpadas: bactérias gulosas de açúcar.'], ['Lavar os dentes vezes demais', 'Lavar demais? É precisamente isso que afasta as bactérias! As cáries vêm de bactérias que adoram açúcar.']], 'As bactérias da boca transformam o açúcar em ácido, que gasta o esmalte. Lavar os dentes e comer menos açúcar protege-os.']
  });
  P('irm', 'medecine', {
    fr:['Pour faire des images du corps, une IRM utilise…', 'Un aimant très puissant', [['Des rayons X', 'Les rayons X, c’est la radio et le scanner. L’IRM, elle, utilise un énorme aimant et des ondes radio.'], ['Des ultrasons', 'Les ultrasons, c’est l’échographie. L’IRM fonctionne avec un aimant très puissant.']], 'L’IRM (imagerie par résonance magnétique) utilise un aimant puissant et des ondes radio : pas de rayons X. Elle montre très bien le cerveau et les muscles.'],
    en:['To make images of the body, an MRI scanner uses…', 'A very powerful magnet', [['X-rays', 'X-rays are for X-ray pictures and CT scans. An MRI uses a huge magnet and radio waves.'], ['Ultrasound', 'Ultrasound is for scans like baby scans. An MRI works with a very powerful magnet.']], 'MRI (magnetic resonance imaging) uses a powerful magnet and radio waves: no X-rays. It shows the brain and muscles very well.'],
    es:['Para hacer imágenes del cuerpo, una resonancia magnética usa…', 'Un imán muy potente', [['Rayos X', 'Los rayos X son para las radiografías y el escáner. La resonancia usa un imán enorme y ondas de radio.'], ['Ultrasonidos', 'Los ultrasonidos son para la ecografía. La resonancia funciona con un imán muy potente.']], 'La resonancia magnética usa un imán potente y ondas de radio: nada de rayos X. Muestra muy bien el cerebro y los músculos.'],
    de:['Um Bilder vom Körper zu machen, nutzt ein MRT…', 'Einen sehr starken Magneten', [['Röntgenstrahlen', 'Röntgenstrahlen nutzen Röntgenbild und CT. Das MRT arbeitet mit einem riesigen Magneten und Radiowellen.'], ['Ultraschall', 'Ultraschall ist für Ultraschalluntersuchungen. Das MRT funktioniert mit einem sehr starken Magneten.']], 'Das MRT (Magnetresonanztomografie) nutzt einen starken Magneten und Radiowellen, keine Röntgenstrahlen. Gehirn und Muskeln sieht man damit sehr gut.'],
    it:['Per fare immagini del corpo, una risonanza magnetica usa…', 'Un magnete potentissimo', [['I raggi X', 'I raggi X servono per radiografie e TAC. La risonanza usa un enorme magnete e onde radio.'], ['Gli ultrasuoni', 'Gli ultrasuoni servono per l’ecografia. La risonanza funziona con un magnete potentissimo.']], 'La risonanza magnetica usa un magnete potente e onde radio: niente raggi X. Mostra molto bene cervello e muscoli.'],
    pt:['Para fazer imagens do corpo, uma ressonância magnética usa…', 'Um íman muito potente', [['Raios X', 'Os raios X são para as radiografias e a TAC. A ressonância usa um íman enorme e ondas de rádio.'], ['Ultrassons', 'Os ultrassons são para a ecografia. A ressonância funciona com um íman muito potente.']], 'A ressonância magnética usa um íman potente e ondas de rádio: sem raios X. Mostra muito bem o cérebro e os músculos.']
  });
  P('echographie', 'medecine', {
    fr:['L’échographie, qui permet de voir un bébé dans le ventre de sa mère, utilise…', 'Des ultrasons', [['Des rayons X', 'Des rayons X sur un bébé ? On les évite justement ! L’échographie utilise des ultrasons, sans danger.'], ['Une caméra avalée', 'Personne n’avale de caméra pour une échographie ! On pose une sonde sur le ventre, qui envoie des ultrasons.']], 'La sonde envoie des sons trop aigus pour nos oreilles ; leur écho sur les organes forme l’image à l’écran.'],
    en:['An ultrasound scan, used to see a baby inside its mother, uses…', 'Sound waves too high for us to hear', [['X-rays', 'X-rays on a baby? They are avoided for exactly that reason! Ultrasound scans use safe sound waves.'], ['A swallowed camera', 'Nobody swallows a camera for a baby scan! A probe on the tummy sends out sound waves.']], 'The probe sends out sounds too high for our ears; their echo off the organs builds the picture on the screen.'],
    es:['La ecografía, que permite ver a un bebé en la barriga de su madre, usa…', 'Ultrasonidos', [['Rayos X', '¿Rayos X a un bebé? ¡Justamente se evitan! La ecografía usa ultrasonidos, sin peligro.'], ['Una cámara tragada', '¡Nadie se traga una cámara para una ecografía! Se apoya una sonda en la barriga que envía ultrasonidos.']], 'La sonda envía sonidos demasiado agudos para nuestro oído; su eco en los órganos forma la imagen en la pantalla.'],
    de:['Eine Ultraschalluntersuchung, mit der man ein Baby im Bauch sieht, nutzt…', 'Ultraschall', [['Röntgenstrahlen', 'Röntgen bei einem Baby? Genau das vermeidet man! Der Ultraschall ist ungefährlich.'], ['Eine verschluckte Kamera', 'Niemand verschluckt dafür eine Kamera! Man setzt einen Schallkopf auf den Bauch, der Ultraschall aussendet.']], 'Der Schallkopf sendet Töne, die zu hoch für unsere Ohren sind; ihr Echo an den Organen ergibt das Bild.'],
    it:['L’ecografia, che permette di vedere un bebè nella pancia della mamma, usa…', 'Gli ultrasuoni', [['I raggi X', 'Raggi X su un bebè? Si evitano proprio! L’ecografia usa ultrasuoni, senza pericolo.'], ['Una telecamera inghiottita', 'Nessuno inghiotte una telecamera per un’ecografia! Si appoggia una sonda sulla pancia che manda ultrasuoni.']], 'La sonda manda suoni troppo acuti per le nostre orecchie; la loro eco sugli organi forma l’immagine sullo schermo.'],
    pt:['A ecografia, que permite ver um bebé na barriga da mãe, usa…', 'Ultrassons', [['Raios X', 'Raios X num bebé? É justamente o que se evita! A ecografia usa ultrassons, sem perigo.'], ['Uma câmara engolida', 'Ninguém engole uma câmara para uma ecografia! Pousa-se uma sonda na barriga que envia ultrassons.']], 'A sonda envia sons demasiado agudos para os nossos ouvidos; o eco nos órgãos forma a imagem no ecrã.']
  });
})();
